  "Đi bộ mất thời gian thực theo khoảng cách. Truyền Tống đến ngay nhưng tốn Bạc. Vùng khoá cần đủ cấp mới vào.": "步行依距離耗真實時間。傳送即刻抵達但花費銀兩。上鎖區域需等級足夠方能進入。",
  "Nhiệm Vụ": "任務",
  "Bốn nhóm theo chu kỳ.": "依週期分四組。",
  "Nhóm": "組別",
  "Số việc": "任務數",
  "Làm mới": "刷新",
  "Thưởng": "獎勵",
  "Tân Thủ": "新手",
  "một lần": "一次",
  "Hằng ngày": "每日",
  "mỗi ngày": "每天",
  "Hằng tuần": "每週",
  "mỗi tuần": "每週",
  "Bạc, Hồn Thạch": "銀兩、魂石",
  "Hằng tháng": "每月",
  "mỗi tháng": "每月",
  "Bạc, Hồn Thạch, Nguyên Bảo": "銀兩、魂石、元寶",
  "Việc được chọn theo cấp người chơi; chỉ tiêu và thưởng co giãn theo đó.": "任務依玩家等級選定；目標與獎勵隨之伸縮。",
  "Phi Cáp Đài": "飛鴿臺",
  "Trung tâm thông báo.": "通知中心。",
  "Gom mọi sự kiện xảy ra khi người chơi vắng mặt: hoạt động hoàn tất, vật phẩm hiếm, đệ tử phá cảnh, tin Tiên Minh, sự kiện giang hồ.": "匯集玩家不在時發生的一切：活動完成、稀有物品、弟子破境、仙盟消息、江湖大事。",
  "Thông báo có thưởng lĩnh trực tiếp tại chỗ. Chấm xanh trên chuông báo còn tin chưa đọc.": "附獎勵的通知可當場領取。鈴鐺上的綠點表示尚有未讀消息。",
  "Phong Vân Bảng": "風雲榜",
  "Bảng xếp hạng toàn giang hồ.": "全江湖排行榜。",
  "Xếp hạng theo Tổng Lv, theo từng nghề, và theo Chiến Lực.": "依總等級、各職業與戰力分別排名。",
  "Giang hồ có sẵn 200 cao thủ mô phỏng: họ lên cấp, đổi hoạt động và đổi vùng theo thời gian thực, nên thứ hạng thay đổi liên tục.": "江湖中有 200 位模擬高手：他們即時升級、更換活動與區域，排名因此不斷變動。",
  "Mọi tài khoản đứng chung <b>một giang hồ</b>. Cùng một lúc, ai mở Phong Vân Bảng cũng thấy đúng những người ấy.": "所有帳號同處<b>一個江湖</b>。同一時刻，任何人打開風雲榜看到的都是同一批人。",
  "Cứ khoảng <b>46 giờ</b> lại có một người nhập giang hồ. Ai đã ở đủ <b>365 ngày</b> thì ẩn cư, rời bảng.": "約每<b>46 小時</b>就有一人踏入江湖。待滿<b>365 天</b>者歸隱，退出榜單。",
  "Nhờ vậy lúc nào cũng có người mới chân ướt chân ráo để đua, chứ bảng không toàn cao thủ.": "因此榜上總有初出茅廬的新人可較量，而非清一色高手。",
  "Riêng <b>10 lão làng</b> không ẩn cư. Họ ở lại mãi, giữ chỗ đỉnh bảng.": "唯獨<b>10 位元老</b>不歸隱。他們永遠留守，穩坐榜首。",
  "Danh Sĩ": "名士",
  "20 nhân vật có tiểu sử và quan hệ.": "20 位人物，各有生平與關係。",
  "<b>20 Danh Sĩ</b> là lớp nhân vật mô phỏng sâu nhất: mỗi người có xuất thân, môn phái, mạch đời, tâm trạng và quan hệ với nhau.": "<b>20 位名士</b>是模擬最深的人物層：每人皆有出身、門派、人生軌跡、心境與彼此關係。",
  "Tương tác": "互動",
