  "Hoa Sơn Phái": "華山派",
  "Thúy Yên Cung": "翠煙宮",
  "Thiên Vương Bang": "天王幫",
  "Thiên Nhẫn Giáo": "天忍教",
  "Ngũ Độc Giáo": "五毒教",
  "Võ Đạo Tông Sư": "武道宗師",
  "Chiến Đấu đạt cảnh giới đại thành — võ học thông thần.": "戰鬥臻於大成——武學通神。",
  "Phủ Thánh": "斧聖",
  "Đốn Củi đăng phong tạo cực — một phủ khai sơn.": "伐木登峰造極——一斧開山。",
  "Khoáng Thần": "礦神",
  "Đào Khoáng thấu địa tầm long — moi tận kim nguyên.": "採礦透地尋龍——掘盡金源。",
  "Ngư Ẩn Tông Sư": "漁隱宗師",
  "Câu Cá đạt thần cảnh — buông câu kinh động thuỷ cung.": "釣魚臻於神境——垂綸驚動水宮。",
  "Luyện Kim Thánh Thủ": "冶煉聖手",
  "Luyện Kim hoả hầu viên mãn — quặng thô thành tinh.": "冶煉火候圓滿——粗礦成精。",
  "Ngự Trù": "御廚",
  "Nấu Ăn đạt thần thủ — sơn hào hải vị tuỳ tâm.": "烹飪臻於神手——山珍海味隨心。",
  "Đan Vương": "丹王",
  "Luyện Đan đăng đỉnh — một lò nên tiên đan.": "煉丹登頂——一爐成仙丹。",
  "Thần Binh Tượng": "神兵匠",
  "Rèn Đúc thông huyền — vạn lần tôi luyện thành thần binh.": "鍛造通玄——千錘百鍊成神兵。",
  "Thiền Tâm Đại Sư": "禪心大師",
  "Thiền Định nhập định viên mãn — tâm như chỉ thuỷ.": "禪定圓滿——心如止水。",
  "Lỗ Ban Tái Thế": "魯班再世",
  "Xây Dựng đạt tuyệt kĩ — lầu son gác tía dựng trong tay.": "建造臻於絕技——朱樓紫閣起於掌中。",
  "Bách Thảo Chân Nhân": "百草真人",
  "Hái Thuốc đến tận cùng — nhìn cỏ biết tính, chạm rễ biết niên.": "採藥臻於化境——觀草知性，觸根知年。",
  "Minh Chủ": "盟主",
  "Phó Minh Chủ": "副盟主",
  "Đường Chủ": "堂主",
  "Hộ Pháp": "護法",
  "Minh Chúng": "盟眾",
  "Tân Nhập": "新入",
  "Tổng Đàn": "總壇",
  "Nhà chính. Nâng lên thì chứa được nhiều người hơn, và minh chúng nộp Minh Cống nhanh hơn.": "主殿。升級後可容納更多人，盟眾繳納盟貢更快。",
  "Binh Khí Khố": "兵器庫",
  "Kho vũ khí. Xây tới cấp nào thì ba kĩ năng Công Kích, Phòng Ngự, Sinh Lực học được tới cấp đó.": "兵器之庫。建至幾級，攻擊、防禦、生命三項技能便可學至幾級。",
  "Tụ Linh Trì": "聚靈池",
  "Ao linh khí. Ai trong minh đi đánh quái cũng được thêm kinh nghiệm.": "靈氣之池。盟中人人打怪皆得額外經驗。",
  "Minh Khố": "盟庫",
  "Kho chung. Chứa được nhiều loại đồ hơn, và minh chúng nộp Bạc về nhiều hơn.": "共用倉庫。可存更多種物品，盟眾上繳銀兩更多。",
  "Trảm Yêu Đài": "斬妖臺",
  "Đài triệu Yêu Vương. Mỗi tuần gọi một con về cho cả minh xúm vào đánh, cấp càng cao con càng dữ và thưởng càng dày.": "召喚妖王之臺。每週召來一頭，全盟齊上圍攻——等級越高妖王越凶，獎勵越厚。",
  "Luyện Đan Phòng": "煉丹房",
  "Phòng luyện đan. Xây tới cấp nào thì bốn quyết kiếm chác — Tham Tài, Lùng Sục, Thổ Mộc, Toạ Quan — học được tới cấp đó.": "煉丹之房。建至幾級，貪財、搜刮、土木、坐觀四訣便可學至幾級。",
  "Tàng Kinh Các": "藏經閣",
  "Gác chứa kinh. Xây tới cấp nào thì bốn quyết tu luyện — Ngộ Đạo, Tụ Hồn, Tầm Bảo, Mục Thú — học được tới cấp đó.": "藏經之閣。建至幾級，悟道、聚魂、尋寶、牧獸四訣便可學至幾級。",
  "Diễn Võ Trường": "演武場",
  "Sân luyện võ. Minh chúng tập trận quen tay, mỗi tuần ngươi được thêm lượt xuất trận đánh Yêu Vương.": "練武之場。盟眾操練嫻熟，每週你多得出戰妖王的次數。",
  "Phi Cáp Trạm": "飛鴿站",
  "Trạm chim đưa thư. Danh tiếng Tiên Minh bay xa, người tìm tới cửa xin nhập minh dày hơn.": "飛鴿驛站。仙盟聲名遠揚，登門求入盟者更多。",
  "Thí Kiếm Đài": "試劍臺",
  "Đài tỉ kiếm. Minh chúng mài nghề trên đài, ra ngoài chém quái ghi được nhiều điểm Chinh Phạt hơn.": "比劍之臺。盟眾臺上磨劍，外出斬妖多得征伐點數。",
  "Bạc": "銀兩",
  "Tiêu vào nguyên liệu, đan dược, công cụ và phí Bí Cảnh.": "用於材料、丹藥、工具與秘境費用。",
  "Hồn Thạch": "魂石",
  "Tiêu vào linh thạch, đan dược và Linh Thú bậc cao.": "用於靈石、丹藥與高階靈獸。",
  "Nguyên Bảo": "元寶",
  "Tiêu vào dung mạo, ô chứa và đổi tên — không mua được sức mạnh.": "用於容貌、儲物格與改名——買不到實力。",
