  "Công cụ không tham gia chiến đấu. Phần cộng của công cụ vào thẳng mẫu số hiệu suất:": "工具不參與戰鬥。工具加成直接計入效率分母：",
  "Chu kỳ thực = thời gian cơ sở ÷ tổng hệ số hiệu suất": "實際週期 = 基礎時間 ÷ 總效率係數",
  "Nguồn: rèn bằng nghề Rèn Đúc, mua ở Thương Điếm, hoặc rơi trong Bí Cảnh. Xem bảng <b>Công Cụ</b> trong Tra Cứu.": "來源：以鍛造打造、在商店購買，或於秘境掉落。詳見查詢中的<b>工具</b>表。",
