  "Trong đó có <b>72 đồ phổ</b> và <b>30 trứng Linh Thú</b>.": "其中包含<b>72 張圖譜</b>與<b>30 顆靈獸蛋</b>。",
  "Hành lý đầy làm mọi hoạt động thu hoạch dừng lại.": "行囊滿時，所有採集活動停止。",
  "Trưng Bày": "展示",
  "Bảy ô khoe đồ ở Hồ Sơ.": "檔案頁的七個展示格。",
  "Giá Trưng Bày nằm ở trang <b>Hồ Sơ</b>, ngay trên khối Trang Bị.": "展示架位於<b>檔案</b>頁，就在裝備區塊上方。",
  "Treo được ba thứ: <b>trang bị</b>, <b>vật phẩm trong túi</b> và <b>linh thú</b>.": "可展示三類：<b>裝備</b>、<b>行囊物品</b>與<b>靈獸</b>。",
  "Bấm một ô trống là mở bảng chọn. Bấm món đã treo là mở thẻ chi tiết của nó.": "點擊空格開啟選擇面板。點擊已展示的物品則開啟其詳情卡。",
  "Nút <b>Sắp Xếp</b> đổi sang chế độ hạ đồ xuống. Bấm <b>Xong</b> để quay lại.": "<b>整理</b>按鈕切換為下架模式。點<b>完成</b>返回。",
  "Giá chỉ <b>trỏ tới</b> thứ ngươi đang có. Bán món hay thả linh thú thì ô tự trống.": "展示架僅<b>指向</b>你現有之物。賣出物品或放生靈獸後，該格自動清空。",
  "Mỗi thứ chỉ treo được một ô. Treo nó sang ô mới thì ô cũ tự nhường chỗ.": "每件物品僅佔一格。移展至新格時，舊格自動騰空。",
  "Trưng Bày thuần trang trí — không cộng một điểm chỉ số nào.": "展示純屬裝飾——不加任何一點屬性。",
  "Động Phủ": "洞府",
  "Nới trần ngoại tuyến và mở công trình tiện ích.": "提升離線上限並開放功能建築。",
  "Chức năng": "功能",
  "Chi tiết": "詳情",
  "Nới trần ngoại tuyến": "提升離線上限",
  "Bậc nhà càng cao, số giờ tính bù càng nhiều": "屋舍等階越高，補算時數越多",
  "Công trình tiện ích": "功能建築",
  "Xây bằng Bạc và nguyên liệu, mất thời gian thực": "以銀兩與材料建造，耗費真實時間",
