  "Công trình có <b>độ bền</b> giảm dần theo thời gian. Công trình hỏng ngừng tác dụng cho tới khi sửa; phí sửa thấp hơn phí xây mới.": "建築的<b>耐久</b>會隨時間下降。損壞的建築在修復前失效；修繕費低於新建費。",
  "Danh Sách Nghề": "職業一覽",
  "10 nghề, trần cấp 100 mỗi nghề.": "10 種職業，每種等級上限 100。",
  "Việc": "工作",
  "Chặt Cây": "砍樹",
  "Khai Khoáng": "開礦",
  "Thái Dược": "摘藥",
  "Luyện Kim": "冶煉",
  "Luyện Quặng": "煉礦",
  "Nấu Ăn": "烹飪",
  "Luyện Đan": "煉丹",
  "Luyện Dược": "煉藥",
  "Rèn Đúc": "鍛造",
  "Rèn Binh Khí": "鍛造兵器",
  "Thiền Định": "禪定",
  "Tĩnh Tọa": "靜坐",
  "Xây Dựng": "建造",
  "Doanh Tạo": "營造",
  "Mỗi nghề có cấp và kinh nghiệm riêng, trần 100. Mở nghề mới cần Tổng Lv đủ và một khoản Bạc; cứ mỗi 80 Tổng Lv mở thêm một nghề, chi phí tăng dần.": "每種職業有獨立等級與經驗，上限 100。開啟新職業需足夠總等級與一筆銀兩；每 80 總等級可多開一職，費用遞增。",
  "Thu Hoạch & Chế Tạo": "採集與製作",
  "Công thức chu kỳ và các nguồn hiệu suất.": "週期公式與各效率來源。",
  "Các nguồn cùng cộng vào mẫu số": "各來源共同計入分母",
  "Cấp nghề": "職業等級",
