  "Vật phẩm thành phẩm, kinh nghiệm nghề": "成品物品、職業經驗",
  "Nguyên liệu bậc cao chỉ có ở vùng cấp cao. Có <b>72 đồ phổ</b> trong trò chơi.": "高階材料僅出現於高等級區域。遊戲中共有<b>72 張圖譜</b>。",
  "Linh Thạch": "靈石",
  "9 loại, cộng kinh nghiệm / hiệu suất / sản lượng.": "9 種，加成經驗 / 效率 / 產量。",
  "Linh Thạch là vật phẩm tiêu hao dùng khi làm nghề. Ba nhánh tác dụng: kinh nghiệm nghề, hiệu suất (rút ngắn chu kỳ), sản lượng mỗi lượt.": "靈石是做職業時使用的消耗品。三類效果：職業經驗、效率（縮短週期）、每輪產量。",
  "Mỗi viên phủ một khoảng thời gian hoạt động, hết thì tự đốt viên cùng loại kế tiếp.": "每顆靈石覆蓋一段活動時間，耗盡後自動燃燒下一顆同類靈石。",
  "Hết sạch thì hoạt động vẫn chạy, chỉ mất phần cộng thêm.": "全部用完後活動照常進行，僅失去加成。",
  "Bảng <b>Linh Thạch</b> trong Tra Cứu ghi mức cộng của từng viên.": "查詢中的<b>靈石</b>表載明每顆的加成。",
  "Đàm Đạo": "談道",
  "10 mạch truyện, mỗi nghề một bậc thầy.": "10 條故事線，每種職業一位宗師。",
  "Mỗi nghề có một nhân vật bậc thầy và một mạch truyện mở dần theo cấp nghề. Cửa vào nằm tại trang của nghề.": "每種職業各有一位宗師，及一條隨職業等級逐步開展的故事線。入口位於該職業的頁面。",
  "Hoàn tất mạch truyện của một nghề cấp <b>Tín Vật</b>, cộng hiệu suất cố định cho nghề đó.": "完成某職業的故事線可獲<b>信物</b>，為該職業提供固定效率加成。",
  "Vòng Đấu": "戰鬥循環",
  "Nhịp 8 giây một trận, diễn tự động.": "每 8 秒一戰，自動進行。",
  "Chiến đấu diễn tự động. Hệ thống nhàn tu chuẩn hoá mỗi vòng cày là <b>8 giây</b>, tương ứng một trận.": "戰鬥自動進行。掛機系統將每輪標準化為<b>8 秒</b>，對應一場戰鬥。",
  "Bộ chiêu đã xếp quyết định thứ tự ra chiêu, mức tiêu Nội Lực và hồi chiêu.": "排好的招式組決定出招順序、內力消耗與冷卻。",
  "Sinh Lực duy trì bằng món ăn và đan dược gắn ở ô tự dùng.": "生命靠自動使用欄中的料理與丹藥維持。",
  "Gục thì chuyển sang trạng thái Suy Yếu, hết thời gian mới đánh tiếp. Vật phẩm đã nhận không mất.": "倒下後進入虛弱狀態，時間結束才繼續作戰。已獲得的物品不會失去。",
  "Có <b>33 loại quái</b> phân bố trên <b>10 vùng</b>. Chỉ số từng con xem ở bảng <b>Quái</b> trong Tra Cứu.": "共<b>33 種怪物</b>分布於<b>10 個區域</b>。各怪屬性詳見查詢中的<b>怪物</b>表。",
  "Ngũ Hành Khắc Chế": "五行剋制",
  "Khắc +30%, bị khắc −20%.": "剋制 +30%，被剋 −20%。",
  "Năm hệ: <b> ·  ·  ·  · </b>. Ngoài ra có <b>Vô Hệ</b> — đòn không thuộc hệ nào, không chịu và không hưởng khắc chế.": "五行：<b> ·  ·  ·  · </b>。另有<b>無系</b>——不屬任何一系的攻擊，不受也不享剋制。",
  "Vòng khắc: Kim → Mộc → Thổ → Thủy → Hỏa → Kim": "相剋循環：金 → 木 → 土 → 水 → 火 → 金",
  "Quan hệ": "關係",
  "Hệ số sát thương": "傷害係數",
  "Đánh vào hệ mình khắc": "攻擊己方所剋之系",
  "Đánh vào hệ khắc mình": "攻擊剋制己方之系",
  "Cùng hệ hoặc Vô Hệ": "同系或無系",
  "không đổi": "不變",
  "Có <b>8 môn phái</b> đặt tên cho các nhánh võ học theo hệ. Chọn nhánh không khoá việc học chiêu của nhánh khác.": "有<b>8 個門派</b>為各系武學分支命名。選擇分支不會鎖住修習其他分支的招式。",
  "Kháng Ngũ Hành": "五行抗性",
  "Trần kháng 50%; Tâm Pháp cho sẵn 20% hệ mình.": "抗性上限 50%；心法自帶本系 20%。",
  "Mỗi hệ có một chỉ số kháng riêng, giảm trực tiếp sát thương của hệ đó.": "每系各有一項抗性，直接降低該系傷害。",
  "Mục": "項目",
  "Giá trị": "數值",
  "Trần kháng mỗi hệ": "每系抗性上限",
  "Kháng sẵn có từ Tâm Pháp cho hệ của nó": "心法對本系自帶的抗性",
  "Nguồn kháng": "抗性來源",
  "Tâm Pháp": "心法",
  "Dòng phụ trang bị": "裝備副詞條",
  "Dòng ẩn Bộ Trang": "套裝隱藏詞條",
  "Đan dược": "丹藥",
  "Quái cũng có kháng riêng. Chỉ số kháng từng con ghi trong bảng <b>Quái</b> và <b>Yêu Vương</b> ở Tra Cứu.": "怪物也各有抗性。各怪抗性載於查詢中的<b>怪物</b>與<b>妖王</b>表。",
  "Cộng Hưởng Ngũ Hành": "五行共鳴",
  "Cộng thẳng % sát thương cho chiêu ĐÚNG hệ đó.": "只為「正是該系」的招式直接加 % 傷害。",
  "<b>Cộng Hưởng</b> của một hệ là <b>phần trăm sát thương cộng thêm cho những chiêu thuộc đúng hệ ấy</b>. Cộng Hưởng Kim chỉ làm mạnh chiêu hệ Kim, không đụng tới chiêu hệ khác.": "某一系的<b>共鳴</b>是<b>為正屬該系的招式追加的傷害百分比</b>。金系共鳴只強化金系招式，不影響其他系的招式。",
  "Sát thương chiêu = sát thương gốc × (1 + Cộng Hưởng của hệ chiêu đó)": "招式傷害 = 基礎傷害 × (1 + 該招所屬系的共鳴)",
  "Ba nguồn Cộng Hưởng": "共鳴的三個來源",
  "Nguồn": "來源",
  "Cho hệ nào": "加成哪一系",
  "Mức": "幅度",
  "hệ của chính Tâm Pháp": "心法自身之系",
  "Bị động võ học": "武學被動",
  "hệ ghi trên bị động": "被動上標明之系",
  "theo từng bị động": "依各被動而定",
  "Trang bị mang hệ": "帶系裝備",
  "hệ của món đồ": "該件裝備之系",
  "theo từng món": "依各件而定",
  "Dòng ẩn <b>7 món</b> của Bộ Trang cũng đổ vào đây — đó là lý do nó ghi dạng “Cộng Hưởng Kim +30%”.": "套裝<b>7 件</b>的隱藏詞條也匯入此處——因此它寫作「金系共鳴 +30%」。",
  "Khi bộ đồ lệch hệ Tâm Pháp": "套裝與心法異系時",
  "Cộng Hưởng <b>không mất đi</b>, nhưng chỉ ăn vào chiêu đúng hệ của nó. Mang Tâm Pháp Hỏa mà mặc bộ cho Cộng Hưởng Kim thì 30% ấy chỉ cộng cho chiêu hệ Kim đang lắp; chiêu hệ Hỏa không nhận gì.": "共鳴<b>不會消失</b>，只是僅作用於同系招式。修火系心法卻穿上給金系共鳴的套裝，那 30% 只加給已裝配的金系招式；火系招式毫無所得。",
  "Ô <b>Cộng Hưởng</b> ở bảng chỉ số chỉ hiện <b>hệ chính</b> (hệ của Tâm Pháp). Các hệ lệch hiện thành chip nhỏ ngay cạnh — nhìn đó để biết mình đang dư Cộng Hưởng ở hệ nào.": "屬性面板的<b>共鳴</b>欄僅顯示<b>主系</b>（心法之系）。異系數值以小徽章顯示在旁——看那裡便知自己哪一系還有多餘共鳴。",
  "Cộng Hưởng <b>khác Khắc Chế</b>: Khắc Chế so hệ mình với hệ đối thủ, còn Cộng Hưởng chỉ nhìn hệ của chính chiêu mình đánh ra.": "共鳴<b>不同於剋制</b>：剋制比較己方與對手之系，共鳴只看自己所出招式之系。",
  "Hiệu Ứng Theo Hệ": "各系效果",
  "Mỗi hệ một hiệu ứng, có tỉ lệ và số nhịp riêng.": "每系一種效果，各有觸發率與節拍數。",
