  "Thể loại nhàn tu, ba trục phát triển song song.": "閒修類型，三條成長主軸並行。",
  "Tiêu Dao Lục là trò chơi <b>nhàn tu</b> (idle) chạy trên trình duyệt. Người chơi đặt một hoạt động, hoạt động tiếp tục chạy khi đóng trình duyệt, và được tính bù khi mở lại.": "《逍遙錄》是一款於瀏覽器執行的<b>閒修</b>（放置）遊戲。玩家設定一項行動，關閉瀏覽器後行動仍持續進行，重新開啟時補算進度。",
  "Không có lớp nhân vật cố định. Ba trục phát triển chạy song song và nuôi lẫn nhau:": "沒有固定的角色職業。三條成長主軸並行，彼此相輔相成：",
