  "Một hoạt động tại một thời điểm; tiến độ tính bù khi vắng mặt.": "同一時間僅一項行動；離開期間進度會補算。",
  "Tại mỗi thời điểm chỉ có <b>một hoạt động chính</b>: làm nghề, chiến đấu, di chuyển, hoặc Bí Cảnh. Chọn hoạt động mới sẽ dừng hoạt động cũ.": "同一時間只有<b>一項主要行動</b>：技藝、戰鬥、移動或秘境。選擇新行動會停止舊行動。",
  "Tiến độ khi đóng trình duyệt được tính bù lúc mở lại, giới hạn bởi trần ngoại tuyến.": "關閉瀏覽器期間的進度會在重開時補算，受離線上限限制。",
  "Trần ngoại tuyến cơ sở 8 giờ, nới thêm theo bậc Động Phủ.": "離線上限基礎為 8 小時，隨洞府等階提高。",
  "Kết quả khi treo máy và khi ngồi xem là <b>như nhau</b>. Hai đường thưởng dùng chung hệ số.": "掛機與在線觀看的結果<b>完全相同</b>。兩條獎勵路徑共用同一套係數。",
