  "Mỗi nghề một cấp riêng; Tổng Lv là tổng tất cả.": "每項技藝各自有等級；總等級為全部總和。",
  "Mỗi nghề có cấp riêng, trần 100, cộng thêm cấp Chiến Đấu. <b>Tổng Lv</b> là tổng các cấp đó.": "每項技藝各有等級，上限 100，再加上戰鬥等級。<b>總等級</b>即這些等級之和。",
