  "Lưu cục bộ; đăng nhập thêm bản đám mây.": "本地存檔；登入後另有雲端存檔。",
  "Trò chơi tự lưu vào trình duyệt sau mỗi thay đổi lớn.": "每次重大變動後，遊戲自動存檔至瀏覽器。",
