  "Độc Nhất": "孤本",
  "Món rơi hoặc rèn ra là <b>bản riêng</b>: cùng tên nhưng dòng phụ bốc khác nhau. Xem chi tiết từng món ở bảng <b>Trang Bị</b> trong Tra Cứu.": "掉落或鍛造的每件裝備都是<b>獨立個體</b>：同名但副詞條各自隨機。詳見查閱中的<b>裝備</b>表。",
  "Dòng Phụ & Cường Hoá": "副詞條與強化",
  "21 loại dòng phụ; 10 bậc thỏi cường hoá.": "21 種副詞條；強化鑄錠共 10 階。",
  "Dòng phụ bốc ngẫu nhiên từ <b>21 loại</b>. Mỗi ô có bộ trọng số riêng, nên dòng nào ra ở ô nào là cố định theo bảng số. Xem bảng <b>Dòng Phụ</b> trong Tra Cứu để biết khoảng giá trị và ô bốc được.": "副詞條自 <b>21 種</b>中隨機抽取。每個欄位各有權重表，故哪個欄位出哪些詞條由數值表固定。數值範圍與可抽欄位詳見查閱中的<b>副詞條</b>表。",
  "Cường hoá": "強化",
  "Tốn Bạc và thỏi kim loại đúng bậc — có <b>10 bậc thỏi</b>.": "消耗銀兩與對應階級的金屬鑄錠——鑄錠共 <b>10 階</b>。",
  "Thất bại không mất món, chỉ mất phí.": "失敗不會失去裝備，僅損失費用。",
  "Các mốc cường hoá cao cần Tinh Thể Yêu Vương.": "高階強化節點需要妖王結晶。",
  "Trang bị rơi từ quái": "怪物掉落裝備",
  "Xác suất rơi trang bị = 0.3% × hệ số thưởng rơi đồ": "裝備掉落機率 = 0.3% × 掉寶加成係數",
  "Trọng số khi đã rơi": "掉落時權重",
  "Xác suất tuyệt đối mỗi trận": "每場絕對機率",
  "Quái không rơi Mảnh Trang Bị Hoàng Kim — Mảnh chỉ đến từ thông quan Bí Cảnh Lv 70+ và Yêu Vương Lv 90+.": "怪物不掉落黃金裝備碎片——碎片僅來自通關 Lv 70+ 秘境與 Lv 90+ 妖王。",
  "Ở mức cơ sở, kỳ vọng khoảng <b>333 trận</b> một món trang bị.": "以基礎機率計，約 <b>333 場</b>戰鬥可得一件裝備。",
  "Bộ Trang": "套裝",
  "11 bộ; dòng ẩn mở ở mốc 3, 5, 7 món.": "共 11 套；隱藏詞條於 3、5、7 件時開啟。",
  "Có <b>11 bộ trang</b>. Mặc đủ số món cùng một bộ mở dòng ẩn tại mốc 3, 5 và 7. Mốc sau bao gồm mốc trước.": "共有 <b>11 套套裝</b>。穿滿同一套裝的件數，即於 3、5、7 件時開啟隱藏詞條。後一門檻包含前一門檻。",
  "Bộ hạng <b>Bạch Kim</b> ghép từ Mảnh Trang Bị theo đồ phổ bộ; đồ phổ rơi ở Bí Cảnh cấp cao.": "<b>白金</b>級套裝以裝備碎片按套裝圖譜拼合；圖譜掉落於高階秘境。",
  "Bảng <b>Bộ Trang</b> trong Tra Cứu ghi đủ dòng ẩn từng mốc, số mảnh mỗi món, và nơi rơi đồ phổ.": "查閱中的<b>套裝</b>表載明各門檻隱藏詞條、每件所需碎片數與圖譜掉落地點。",
