  "Bán nguyên liệu cơ bản, mồi câu, món ăn, và vật phẩm trang trí như ảnh đại diện và ảnh nền hồ sơ.": "出售基礎材料、魚餌、菜餚，以及頭像與檔案背景等裝飾物品。",
