  "Đạt đủ điều kiện thì danh hiệu tự mở khoá.": "達成條件後稱號自動解鎖。",
  "<b>Chỉ danh hiệu đang đeo mới cộng chỉ số.</b> Mở được nhiều cũng không cộng dồn — mỗi lúc chỉ đeo được một cái.": "<b>只有佩戴中的稱號才加屬性。</b>解鎖再多也不疊加——一次只能佩戴一個。",
  "Dòng chỉ số ghi trên mỗi thẻ là <b>số bạn sẽ nhận nếu đeo cái đó</b>, không phải số đang có.": "每張卡上的屬性行是<b>佩戴該稱號時將獲得的數值</b>，而非當前擁有的數值。",
  "Vào <b>Tàng Hiệu Các</b>, bấm một danh hiệu đã mở là đeo. Danh hiệu đang đeo hiện ngay cạnh tên nhân vật.": "進入<b>藏號閣</b>，點選已解鎖的稱號即可佩戴。佩戴中的稱號顯示在角色名旁。",
