  "Huy Hiệu": "徽章",
  "11 huy hiệu, mốc cấp 100.": "11 枚徽章，100 級里程碑。",
  "Mỗi nghề đạt <b>cấp 100</b> cấp một huy hiệu. Đủ bộ <b>11 huy hiệu</b> tương ứng cày trọn mọi nghề.": "每項職業達到<b>100 級</b>授一枚徽章。集滿<b>11 枚徽章</b>即代表練滿所有職業。",
  "Danh sách ở bảng <b>Huy Hiệu</b> trong Tra Cứu.": "清單載於查詢中的<b>徽章</b>表。",
