  "28 mốc theo chuỗi ngày.": "按連續天數計 28 個里程碑。",
  "Điểm danh tính theo chuỗi ngày vào chơi liên tiếp, có <b>28 mốc thưởng</b>.": "簽到按連續遊玩天數計，共<b>28 個獎勵里程碑</b>。",
  "Một số mốc cấp buff cộng kinh nghiệm mọi nguồn trong một khoảng thời gian.": "部分里程碑授予限時增益，提升所有來源經驗。",
