  "Ba máy đối thủ, đánh theo lượt, cược Trù Mã": "三個電腦對手，輪流出牌，以籌碼下注",
  "Binh Xập Xám": "十三水",
  "Xếp bài bàn 3D": "3D 牌桌理牌",
  "Bốn nhà, mỗi nhà xếp 13 lá thành ba chi, cược Trù Mã": "四家，每家將 13 張牌排成三墩，以籌碼下注",
  "Tiến Lên Trung Quốc": "跑得快",
  "Ba nhà, bộ 48 lá, cược Trù Mã": "三家，48 張牌組，以籌碼下注",
  "Cờ Tướng và Ngũ Tử Kỳ dùng chung điểm Kỳ Hồn và danh hiệu Kỳ Nghệ.": "象棋與五子棋共用棋魂點數與棋藝稱號。",
  "Toàn Màn Hình": "全螢幕",
  "Sáu bàn 3D đều có nút <b>Toàn Màn Hình</b> ở cột nút bên bàn: bàn phủ kín màn hình, không còn thanh đầu trang hay danh mục. Trên điện thoại, máy tự xoay ngang. Bấm lại — hoặc phím Esc — để thu về.": "六張 3D 棋牌桌都在桌旁按鈕欄設有<b>全螢幕</b>按鈕：桌面鋪滿螢幕，不再有頂欄與選單。手機上會自動轉為橫向。再按一次——或按 Esc 鍵——即可還原。",
  "Trù Mã — đồng riêng của chiếu bài": "籌碼——牌桌專屬貨幣",
  "Ba trò bài — Tiến Lên, Tiến Lên Trung Quốc và Binh Xập Xám — cược bằng <b>Trù Mã</b>, không phải Bạc. Đổi Bạc lấy Trù Mã theo tỉ giá <b>1 đổi 1</b>, và chỉ đổi được một chiều.": "三款紙牌遊戲——進升、跑得快與十三水——以<b>籌碼</b>下注，而非銀兩。銀兩兌換籌碼比率<b>1 比 1</b>，且只能單向兌換。",
  "Trù Mã <b>không đổi ngược lại thành Bạc</b>. Nhờ vậy thắng bài không sinh ra Bạc — các trò này cách ly khỏi kinh tế chính, không ảnh hưởng cân bằng cày cuốc.": "籌碼<b>不能換回銀兩</b>。因此贏牌不會產生銀兩——這些遊戲與主經濟隔離，不影響修煉平衡。",
