  "Tính theo": "計數依據",
  "Cộng lẻ": "單項加成",
  "Chiến Sĩ": "戰士",
  "Thiết cốt cương thân, chính khí ngút trời. Đao thương qua tay hóa sấm sét, lấy cương mãnh phá vạn pháp — chính diện giao phong chẳng chút nao núng.": "鐵骨鋼身，正氣沖天。刀槍過手化雷霆，以剛猛破萬法——正面交鋒毫不退縮。",
  "+10% Lực Đạo EXP": "力道經驗 +10%",
  "+5% Chiến Đấu EXP": "戰鬥經驗 +5%",
  "Ám Vệ": "暗衛",
  "Ẩn thân trong bóng tối, đến đi tựa gió thoảng. Một nhát đoạt mệnh giữa chớp mắt, thân pháp quỷ dị khiến địch chưa kịp thấy bóng đã thân thủ dị xứ.": "匿身暗影，來去如風。眨眼間一擊奪命，身法詭異，敵人未見其影已身首異處。",
  "+5% Thân Pháp EXP": "身法經驗 +5%",
  "+10% Hiệu suất săn": "狩獵效率 +10%",
  "Rong ruổi chân trời, cung tiễn bất ly thân. Mũi tên rời dây xuyên mây vọng nguyệt — lấy khoảng cách làm khiên, lấy giang hồ làm nhà.": "浪跡天涯，弓箭不離身。離弦之箭穿雲望月——以距離為盾，以江湖為家。",
  "+7% Linh Xảo EXP": "靈巧經驗 +7%",
  "+8% Hiệu suất săn": "狩獵效率 +8%",
  "Rìu nặng trên vai, sống đời sơn lâm. Mỗi nhát bổ xuống vang động núi rừng, gỗ quý chất đầy — bậc thầy đốn mộc chốn thâm sơn.": "重斧扛肩，棲身山林。每一斧落下震動山野，良木成堆——深山伐木的宗師。",
  "+10% Đốn Củi EXP & Hiệu suất": "伐木經驗與效率 +10%",
  "Lăn lộn nơi hầm sâu lòng đất, mắt tinh nhìn thấu mạch khoáng. Búa chim nện đá toé lửa, moi tận long mạch lấy kim ngọc châu báu.": "摸爬於地底深坑，慧眼看穿礦脈。鶴嘴鋤敲石迸火，掘盡龍脈取金玉珠寶。",
  "+10% Đào Khoáng EXP & Hiệu suất": "採礦經驗與效率 +10%",
  "Ngư Ông": "漁翁",
  "Một cần buông xuống, tĩnh tọa bên sông. Tâm như nước lặng chờ thời — kiên nhẫn đợi một khắc, cá lớn ắt cắn câu.": "一竿垂下，靜坐江邊。心如止水待時機——耐心守候一刻，大魚必然上鉤。",
  "+10% Câu Cá EXP & Hiệu suất": "釣魚經驗與效率 +10%",
  "Tay dao thớt biến sơn hào hải vị thành cao lương. Lửa đượm hương bay, một bàn tiệc đãi anh hùng thiên hạ, no lòng ấm dạ lữ khách phong trần.": "刀俎之間化山珍海味為佳餚。火旺香飄，一席盛宴款待天下英雄，暖飽風塵旅人。",
  "+10% Nấu Ăn EXP & Hiệu suất": "烹飪經驗與效率 +10%",
  "Thợ Luyện Kim": "冶煉師",
  "Đứng giữa lò lửa ngút trời, quặng thô qua tay hóa tinh kim. Nghe hơi nóng mà đoán độ già non, luyện ra thỏi sáng loáng cho bậc thợ rèn.": "立於沖天爐火之間，粗礦過手化精金。聽熱氣而辨火候，煉出亮錠供鍛匠之用。",
  "+10% Luyện Kim EXP & Hiệu suất": "冶煉經驗與效率 +10%",
  "Ngự Thú Sư": "御獸師",
  "Lòng thông vạn vật, ý thấu muông thú. Thuần phục linh thú sơn lâm làm bạn đồng hành — một tiếng sáo ngân, cả bầy nghe lệnh.": "心通萬物，意曉禽獸。馴服山林靈獸為伴——一聲笛響，群獸聽令。",
  "+10% Ngự Thú EXP": "御獸經驗 +10%",
  "Phế Nhân": "廢人",
  "Kẻ tu hành gập ghềnh nhất thiên hạ: căn cơ hao tổn, mỗi bước tiến đẫm mồ hôi xương máu. Chỉ dành cho kẻ ngạo nghễ dám thách thức chính số mệnh.": "天下最坎坷的修行者：根基受損，每進一步皆浸血汗。只留給敢向命運挑戰的傲骨之人。",
  "-50% MỌI EXP": "全部經驗 -50%",
  "Lưu Đày": "流放",
  "Bị giang hồ ruồng bỏ, một thân một bóng bôn tẩu. Không bằng hữu, không giao dịch — chỉ có chính mình và con đường cô độc trải dài phía trước.": "遭江湖遺棄，孤身隻影奔走。無朋友，無交易——只有自己與眼前漫長的孤獨之路。",
  "Cấm Giao Dịch": "禁止交易",
  "-50% phí Truyền Tống": "傳送費 -50%",
  "Ma Chủng": "魔種",
  "Thân mang tà chú thượng cổ, nghịch thiên mà tu. Con đường gian nan bậc nhất thế gian — kẻ nhụt chí chớ dại bước vào, vinh quang chỉ thuộc về kẻ cuồng nhất.": "身負上古邪咒，逆天而修。世間最艱難之路——志弱者切莫踏入，榮耀只屬於最瘋狂之人。",
  "Lưu Đày + Phế Nhân": "流放 + 廢人",
  "Kỹ Năng": "技能",
  "Khổ Tu (Khóa — thử thách cực khó)": "苦修 (鎖定 — 極難挑戰)",
  "Rìu nặng trên vai, bậc thầy đốn mộc chốn thâm sơn.": "重斧扛肩，深山伐木的宗師。",
  "Khoáng Phu": "礦夫",
  "Mắt tinh nhìn thấu mạch khoáng, moi tận kim ngọc lòng đất.": "慧眼看穿礦脈，掘盡地底金玉。",
  "Tĩnh tọa bên sông, kiên nhẫn đợi một khắc cá lớn cắn câu.": "靜坐江邊，耐心守候大魚上鉤的一刻。",
  "Trù Sư": "廚師",
  "Tay dao thớt biến sơn hào hải vị thành cao lương.": "刀俎之間化山珍海味為佳餚。",
  "Nghe hơi nóng mà đoán độ già non, luyện quặng thành tinh kim.": "聽熱氣而辨火候，煉礦成精金。",
  "Phối chế đan dược, luyện linh thạch trợ tu.": "調配丹藥，煉製靈石助修。",
  "Thiết Tượng": "鐵匠",
  "Rèn binh khí, đúc giáp trụ — lửa đượm thép reo.": "鍛造兵器，鑄造甲冑——火旺鋼鳴。",
  "Thiền Sư": "禪師",
  "Tĩnh tâm ngộ đạo, vun bồi nội tâm tịch lặng.": "靜心悟道，涵養內心寂靜。",
  "Bậc thầy kiến tạo, dựng động phủ vững bền.": "建造宗師，築就穩固洞府。",
  "Một giỏ trúc lội khắp sơn dã, cỏ nào là thuốc cỏ nào là độc — nhìn là biết.": "一簍竹筐走遍山野，何草為藥何草為毒——一眼便知。",
  "+0.3% Công": "攻擊 +0.3%",
