  "Một đốm lửa nhỏ, thiêu vạn dặm khô.": "星火一點，焚盡萬里枯原。",
  "Tỉ lệ bạo kích +2%/cấp (bạo ×1.6)": "暴擊率 +2%/級 (暴擊 ×1.6)",
