  "Địch đang cháy nhận +30% sát thương": "燃燒中的敵人受到 +30% 傷害",
  "Bạo kích ×2.4 và thiêu địch thêm": "暴擊 ×2.4 並額外灼燒敵人",
  "Thổ": "土",
  "Ô Thuẫn — giáp & phản đòn": "盾格 — 護甲與反擊",
  "Núi không dời, giáp không vỡ.": "山不移，甲不破。",
  "Phòng ngự ô Thuẫn +6%/cấp": "盾格防禦 +6%/級",
  "Có Hộ Thuẫn → phản 25% sát thương bị chặn": "持有護盾 → 反彈 25% 被擋傷害",
  "Đầu lượt tích thêm Hộ Thuẫn": "回合開始額外積護盾",
  "Miễn đòn nặng đầu tiên mỗi trận": "每場免疫第一次重擊",
  "Ô Kiếm — xuyên giáp & bạo kích": "劍格 — 破甲與暴擊",
  "Kiếm ra khỏi vỏ, tất thấy phân thắng bại.": "劍出鞘，必分勝負。",
  "Sát thương ô Kiếm +6%/cấp": "劍格傷害 +6%/級",
  "Xếp ≥4 ô Kiếm → đòn ấy +50% sát thương": "消除 ≥4 劍格 → 該擊 +50% 傷害",
  "Đang có Hộ Thuẫn → bạo kích +25%": "持有護盾 → 暴擊 +25%",
  "Đòn Kiếm kết liễu địch dưới 15% Sinh Lực": "劍擊處決生命低於 15% 的敵人",
  "Thủy": "水",
  "Ô Khí — sạc chiêu & kiểm soát": "氣格 — 蓄招與控制",
  "Nước không tranh, mà thắng vạn vật.": "水不爭，而勝萬物。",
  "Tụ Khí từ ô Khí +5%/cấp": "氣格聚氣 +5%/級",
  "Xếp ≥4 ô Khí → địch hoãn đòn 1 lượt": "消除 ≥4 氣格 → 敵方攻擊延遲 1 回合",
  "Dùng chiêu → sinh 2 ô Khí": "施放技能 → 生成 2 氣格",
  "Mỗi trận 1 lần nối lượt vượt giới hạn": "每場 1 次超上限接續回合",
  "Kiếm Khí Trảm": "劍氣斬",
  "Chém 55 sát thương thẳng vào địch và quét sạch một hàng ô ngang trên bàn.": "對敵直劈 55 點傷害，並掃清盤面一整橫排。",
  "Khí tụ thành phong — kiếm khai nhất tuyến.": "氣聚成鋒 — 劍開一線。",
  "Hoán Tinh Di Đẩu": "換星移斗",
  "Đổi chỗ hai ô bất kỳ trên bàn, không cần nằm kề — tự tay xếp combo.": "交換盤面任意兩格，無須相鄰 — 親手排出連擊。",
  "Dời sao đổi đẩu — càn khôn tại thủ.": "移星換斗 — 乾坤在手。",
  "Huyết Sát": "血煞",
  "Mỗi ô Kiếm trên bàn nổ: mỗi ô gây 4 sát thương và hồi 2 máu cho ngươi, rồi vỡ.": "盤面每個劍格引爆：每格造成 4 點傷害並為你回復 2 點生命，隨後碎裂。",
  "Kiếm khát máu tanh — một chém hồi sinh.": "劍渴血腥 — 一斬回生。",
  "Hoàng Kim Nhất Kích": "黃金一擊",
  "Mỗi ô Bảo phá được dồn vào kho vàng; xả kho gây sát thương bằng số điểm đã tích — càng gom càng nặng.": "每破一寶格皆存入金庫；釋放時造成等同累積點數的傷害 — 越積越重。",
  "Vàng ròng đúc kiếm — một vựng nghìn lượng.": "真金鑄劍 — 一揮千兩。",
  "Ngũ Hành Đại Chuyển": "五行大轉",
  "Biến cả vùng 3×3 giữa bàn thành một loại ô ngẫu nhiên — tạo đại combo tức thì.": "將盤面中央 3×3 區域化為同一種隨機格 — 瞬間造出大連擊。",
  "Ngũ hành đại chuyển — sắc quy nhất thể.": "五行大轉 — 色歸一體。",
  "Ô Long Giao Tranh": "烏龍交爭",
  "Nếu địch có ô Độc: hóa hết thành ô Kiếm và phản độc về địch. Nếu không: gieo Độc lên địch.": "若敵方有毒格：全數化為劍格並將毒反施其身。若無：對敵播毒。",
  "Rồng đen cản ngược — độc phản về nguồn.": "烏龍逆截 — 毒返其源。",
  "Ngưng Sương Quyết": "凝霜訣",
  "Đóng băng địch: bỏ qua đòn đánh kế và lượt rải Độc kế của địch.": "冰封敵人：跳過其下一次攻擊與下一輪撒毒。",
  "Sương giăng vạn vật — tĩnh chỉ sát cơ.": "霜籠萬物 — 靜止殺機。",
  "Ngũ Lôi Chính Pháp": "五雷正法",
  "Giáng 8 sát thương lên mỗi ô đặc biệt rồi kích nổ tất cả, nổ dây chuyền Hợp Bích toàn bàn.": "對每個特殊格降下 8 點傷害並全數引爆，全盤連鎖合璧爆發。",
  "Ngũ lôi oanh đỉnh — quần tà tận diệt.": "五雷轟頂 — 群邪盡滅。",
  "Tụ Sa Thành Tháp": "聚沙成塔",
  "Tích Lũy": "積累",
  "Xóa càng nhiều ô trong một đòn, hiệu lực càng tăng vọt (một đòn 6 ô mạnh hơn hẳn hai đòn 3 ô). Tính tối đa 9 ô mỗi đòn.": "一擊消除越多格，效果越是暴增 (一次 6 格遠勝兩次 3 格)。每擊最多計 9 格。",
  "Tích cát vi sơn — nhất kích thiên quân.": "積沙為山 — 一擊千鈞。",
  "Càn Khôn Nghịch Chuyển": "乾坤逆轉",
  "Sinh Hóa": "生化",
  "Ô mới rơi xuống thiên về loại kế trong vòng Ngũ Hành (Kiếm, Khí, Bảo, Tâm, Thuẫn), giúp chủ động gom chuỗi liên hoàn.": "新落下的格偏向五行循環的下一種 (劍、氣、寶、心、盾)，便於主動串起連環。",
  "Vạn vật tương sinh — diệt một, sinh một.": "萬物相生 — 滅一，生一。",
  "Hoá Độc Đại Pháp": "化毒大法",
  "Dụng Độc": "用毒",
  "Mỗi ô Độc của địch ngươi phá được nạp 1 Độc Tinh (tối đa 8). Đòn Kiếm kế cộng +4 sát thương mỗi Độc Tinh rồi xả sạch.": "每破一個敵方毒格儲入 1 枚毒精 (至多 8)。下一次劍擊每枚毒精 +4 傷害，隨後清空。",
  "Độc nhập ta tạng — hoàn lại kẻ gieo.": "毒入我臟 — 還於播毒者。",
  "Kim Cang Hộ Thể": "金剛護體",
  "Mỗi lượt 25% Hộ Thuẫn hiện có dồn thẳng vào đòn Kiếm kế (không hao Hộ Thuẫn) — càng thủ, phản đòn càng nặng.": "每回合當前護盾的 25% 直接灌入下一次劍擊 (不消耗護盾) — 守得越厚，反擊越重。",
  "Thân như kim thạch — phản chấn bách địch.": "身如金石 — 反震百敵。",
  "Thái Cực Vô Cực": "太極無極",
  "Vận Khí": "運氣",
  "Tạo ô đặc biệt được +15 Khí; kích nổ hoặc Hợp Bích +8 Khí. Trần nối lượt liên tiếp tăng từ 2 lên 3.": "造出特殊格 +15 氣；引爆或合璧 +8 氣。連續接續回合上限由 2 升至 3。",
  "Nhất khí hóa tam thanh — trận trung sinh trận.": "一氣化三清 — 陣中生陣。",
  "Thôn trang yên bình, đồng cỏ xanh và nông trại nhỏ.": "寧靜村莊，綠野農舍點點。",
  "Rừng già rậm rạp, gió thì thầm giữa tán cây.": "蒼蒼老林，風在樹冠間低語。",
  "Cổ thành phồn hoa, trung tâm giao thương.": "古城繁華，商貿中樞。",
  "Hang động pha lê lấp lánh, khoáng mạch phong phú.": "水晶洞窟熠熠生輝，礦脈豐饒。",
  "Đỉnh núi chọc trời, tuyết phủ quanh năm.": "山峰插天，終年積雪。",
  "Ốc đảo huyền ảo giữa sa mạc, ẩn chứa kỳ trân.": "大漠之中的奇幻綠洲，暗藏奇珍。",
  "Vườn hoa lơ lửng giữa tầng mây Aetheria.": "懸浮於艾瑟利亞雲層間的花園。",
  "Đài quan sát tinh tú, nơi linh khí hội tụ.": "觀星之臺，靈氣匯聚之地。",
  "Hải đảo bí ẩn, sương mù vây phủ tịch mịch.": "神祕海島，霧鎖寂寥。",
  "Tòa thành tối thượng — đích đến của cao thủ.": "至高之城 — 高手的終點。",
