  "Tuần lộc gạc trắng dẫn đầu đàn, vó nó đạp lên tuyết mà không để lại vết.": "白角馴鹿走在鹿群最前，蹄踏雪上不留痕跡。",
  "Thổ tối thượng + Choáng CHẮC CHẮN": "土之至尊 + 必定暈眩",
  "Mô phỏng thần lực Bàn Cổ khai thiên, giáng xuống một ấn nặng tựa cả dãy núi. Mặt đất nứt toác thành vực, khe nứt rực đỏ như gân dung nham — địch nhân bị chấn cho hồn phách lìa khỏi xác, đứng còn chẳng nổi.": "仿盤古開天神力，降下一印重若群山。大地崩裂成淵，裂縫赤紅如熔岩之脈 — 敵人被震得魂飛魄散，站都站不穩。",
  "thạch ấn nặng tựa non cao giáng xuống": "重若高山的石印轟然落下",
  "đất nứt toác, khe sâu rực đỏ dung nham": "大地崩裂，深壑赤紅如熔岩",
  "một ấn trấn nhạc, địch ngã quỵ bất động": "一印鎮嶽，敵人癱倒不動",
  "Đỉnh cao Hậu Thổ — Choáng CHẮC CHẮN 100%. Khoá cứng địch một hiệp trọn vẹn, dọn đường cho cả bộ liên hoàn.": "后土之巔 — 100%必定暈眩。將敵人整整封鎖一回合，為整套連招開路。",
  "Vô Tướng Sát Kiếp": "無相殺劫",
  "Vô Hệ tối thượng — miễn khắc hệ": "無系至尊 — 免疫五行剋制",
  "Không hình không tướng, không hệ không khí — chỉ còn thuần một đạo sát ý. Kình lực nén tới cực hạn rồi vỡ ra, không khí rách thành vệt chân không; ngũ hành sinh khắc tới đây thảy đều vô nghĩa.": "無形無相，無系無氣 — 只餘純粹一道殺意。勁力壓至極限而後迸裂，空氣撕成真空之痕; 五行生剋至此皆屬虛無。",
  "kình lực vỡ ra, không khí rách thành vệt": "勁力迸裂，空氣撕裂成痕",
  "một đạo sát ý vô hình quét ngang": "一道無形殺意橫掃而過",
  "vô tướng vô sắc, ngũ hành thảy vô dụng": "無相無色，五行皆無用",
  "Đỉnh cao thuần lực — chẳng sợ khắc kháng ngũ hành. Quân bài tẩy khi gặp địch khắc hệ mình.": "純力之巔 — 不懼五行剋抗。遭遇剋制己系之敵時的底牌。",
  "+80% sát thương trong 6 hiệp": "6回合內+80%傷害",
  "Thu tâm về một mối, thần giao cùng trời đất. Chân khí quanh thân hoá thành trụ sáng vươn thẳng lên chín tầng mây, vòng thái cực xoay quanh không dứt — trong khoảnh khắc ấy, người chính là thiên địa.": "收心歸一，神交天地。周身真氣化作光柱直上九霄，太極之環旋轉不息 — 那一瞬，人即天地。",
  "trụ sáng vươn thẳng lên chín tầng mây": "光柱直上九霄",
  "vòng thái cực xoay quanh, khí thế áp cả trời": "太極環旋轉，氣勢壓蒼穹",
  "thần giao thiên địa, một niệm mà vạn pháp tuỳ tâm": "神交天地，一念萬法隨心",
  "Đỉnh cao tăng ích — gần gấp đôi sát thương. Bật rồi tung Thái A hoặc Viêm Đế, một nhịp định thắng bại.": "增益之巔 — 傷害近乎翻倍。開啟後再出太阿或炎帝，一擊定勝負。",
  "Lấy hỏa luyện thân, công pháp bạo liệt — càng đánh càng hăng.": "以火煉身，功法暴烈 — 越戰越勇。",
  "Hàn Băng Cung": "寒冰宮",
  "Lấy nhu khắc cương, hàn khí trầm ổn — thiên khống chế & bền bỉ.": "以柔克剛，寒氣沉穩 — 擅控制 & 持久。",
  "Mô phỏng lẽ sinh trưởng vạn vật — độc khí âm ỉ, tự sinh tự dưỡng.": "仿萬物生長之理 — 毒氣陰蘊，自生自養。",
  "Chân khí ngưng như kim loại, mũi nhọn vô song — phá giáp, nhất kích tất sát.": "真氣凝如金鐵，鋒芒無雙 — 破甲，一擊必殺。",
  "Hậu Thổ Trang": "后土莊",
