  "Sơ": "初",
  "Sảnh đường chiêu hiền nạp sĩ — nơi quy tụ anh tài bốn phương về dưới trướng tông môn. Bậc càng cao, sức chứa môn đồ càng rộng; cũng là chốn truyền hịch Chiêu Hiền vang khắp giang hồ.": "招賢納士之堂 — 四方英才匯聚於宗門麾下之地。層級越高，容納門徒越多；亦是傳檄招賢、名動江湖之所。",
  "Giáo trường luyện võ, ngày đêm vang tiếng binh khí va chạm. Đệ tử khổ luyện nơi đây, đạo cơ ngày một vững, tu vi tăng tiến mau hơn — mở rộng trường thì cả tông cùng hưởng.": "練武教場，日夜兵刃交擊之聲不絕。弟子於此苦練，道基日穩，修為精進更速 — 擴建教場則全宗同霑其惠。",
  "Lầu cất giữ kinh thư bí lục của môn phái. Đệ tử nghiền ngẫm điển tịch, lĩnh ngộ huyền cơ — tích góp đều đặn thành Điểm Đấu Giá theo thời gian.": "收藏門派經書秘錄之樓。弟子研讀典籍，領悟玄機 — 隨時間穩定累積競拍點數。",
  "Đan phòng của tông môn, lò lửa quanh năm không tắt. Theo cổ phương mà nung luyện nguyên liệu trong Túi Đồ thành linh đan đột phá — mỗi mẻ tốn thời gian luyện. Bậc cao mở thêm lò và đan phẩm cao hơn.": "宗門丹房，爐火終年不熄。依古方將袋囊中的材料煉成突破靈丹 — 每爐皆需煉製時間。層級越高，增開丹爐並可煉更高丹品。",
  "Khu vườn ươm trồng linh dược, sương khói lượn quanh các luống đất. Mỗi luống nuôi một vị nguyên liệu, đủ ngày thì chín, hái về Túi Đồ. Bậc cao mở thêm luống và trồng được linh dược bậc cao.": "培植靈藥的園圃，霧靄繚繞田畦。每一畦育一味材料，時日一到便熟，採收入袋囊。層級越高，增開田畦並可種更高階靈藥。",
  "Luyện Khí Các": "煉器閣",
  "Gác lò rèn của tông môn, đe nung đỏ lửa, búa gõ vang chan chát. Tôi luyện gia bảo đệ tử đang đeo lên một tầng uy lực — bậc càng cao thì rèn được càng sâu.": "宗門鍛爐之閣，砧上火紅，錘聲鏗鏘。將弟子佩戴的傳家寶淬煉出更上一層威力 — 層級越高，鍛得越深。",
  "Giảng Đạo Đường": "講道堂",
  "Giảng đường thâm u, cao nhân thuyết đạo cho hậu bối nghe. Thính giảng lâu ngày khai mở tâm khiếu — NÂNG TRẦN tư chất đệ tử, giúp kẻ căn cơ tầm thường vươn xa hơn số trời định. (Đắc Đạo vẫn là cảnh giới chỉ Thiên Tư chạm tới.)": "幽深講堂，高人為後輩說道。久聽講道開啟心竅 — 提升弟子資質上限，讓根基平庸者超越天定之數。(得道仍是唯有天資方能觸及的境界。)",
  "Đại trận dẫn linh khí trời đất quy tụ về sơn môn, vận khí hanh thông cát tường. Linh khí dồi dào giúp Khí Vận tông môn tăng tiến, đồng thời bồi thêm tốc độ tu luyện cho toàn môn.": "引天地靈氣匯聚山門之大陣，運勢亨通吉祥。靈氣充沛使宗門氣運日增，並為全門加持修煉速度。",
  "Đãi Khách Các": "待客閣",
  "Lầu tiếp đãi tân khách bốn phương, rượu thơm trà nóng quanh năm. Nơi tông môn kết giao các phái giang hồ, đón sứ giả gây dựng bang giao — bậc cao thì đón được nhiều khách quý, uy danh vang xa.": "接待四方賓客之樓，美酒香茗終年不斷。宗門於此結交江湖各派，迎使節締結邦交 — 層級越高，能接待越多貴客，威名遠播。",
  "Đường nghiêm trị gia pháp môn quy, roi đồng giới xích lạnh người. Nơi tra xét kẻ sinh tâm ma, xử trí phản đồ, gột cờ xấu giữ sơn môn thanh tịnh — bậc cao thì uy nghiêm càng trọng, trấn tâm ma càng sâu.": "嚴執家法門規之堂，銅鞭戒尺令人生寒。查究心魔滋生者，處置叛徒，滌除穢氣以保山門清淨 — 層級越高威嚴越重，鎮壓心魔越深。",
  "Luận Võ Đường": "論武堂",
  "Giảng võ đường cho đệ tử tỉ thí cao thấp, binh khí lách cách suốt ngày. Nơi luận bàn võ học, giao đấu nâng cao sĩ khí toàn môn — bậc cao thì mở thêm đối thủ và đài luận võ.": "供弟子比試高下之演武堂，兵刃終日鏗鏘。於此論武切磋，比鬥提振全門士氣 — 層級越高，增開對手與論武臺。",
  "Tổ Sư Điện": "祖師殿",
  "Điện thờ tổ sư lịch đại, khói hương nghi ngút trang nghiêm. Nơi cung phụng tiền nhân khai phái, ghi danh đệ tử Xuất Sư, Trưởng Lão cùng những người đã khuất — bậc cao thì bài vị càng nhiều, ấm phúc càng dày.": "供奉歷代祖師之殿，香火裊裊莊嚴肅穆。奉祀開派先人，錄入出師弟子、長老與已故之人 — 層級越高牌位越多，蔭福越厚。",
  "Trở thành đệ nhất cao thủ": "成為第一高手",
  "Phục hưng môn hộ đã tàn": "復興沒落門戶",
  "Báo mối huyết hải thâm thù": "報血海深仇",
  "Cầu một đạo trường sinh": "求一道長生",
  "Hành hiệp trượng nghĩa khắp thiên hạ": "行俠仗義遍天下",
  "Tìm lại cố nhân thất lạc": "尋回失散故人",
  "Phá vỡ giới hạn trời định": "打破天定極限",
  "Tụ Linh Thảo": "聚靈草",
  "Hàn Tinh Thạch": "寒晶石",
  "Bách Niên Linh Chi": "百年靈芝",
  "Huyền Thiết Tinh": "玄鐵精",
  "Cửu Diệp Linh Sâm": "九葉靈參",
  "Tinh Hồn Thạch": "精魂石",
  "Ăn mày lưu lạc": "流浪乞兒",
  "Một đứa ăn mày nhặt được bên đường ngày mưa, gầy guộc nhưng ánh mắt không chịu khuất phục.": "雨天在路邊撿回的乞兒，瘦骨嶙峋，眼神卻不肯屈服。",
  "Công tử sa sút": "沒落公子",
  "Tiểu thư sa sút": "沒落千金",
  "Công tử của một gia tộc nay đã lụi tàn, mang trong lòng nỗi hận phục hưng môn hộ.": "沒落家族的公子，心中懷著復興門戶的執念。",
  "Tiểu thư của một gia tộc nay đã lụi tàn, mang trong lòng nỗi hận phục hưng môn hộ.": "沒落家族的千金，心中懷著復興門戶的執念。",
  "Võ lâm thế gia": "武林世家",
  "Hậu duệ một thế gia võ lâm, căn cơ vững vàng, kiêu hãnh trong huyết quản.": "武林世家之後，根基紮實，血脈中流著驕傲。",
  "Tội đồ hoàn lương": "改邪歸正",
  "Từng là kẻ sát nhân khét tiếng, nay rửa tay gác kiếm tìm một chốn dung thân.": "曾是惡名昭彰的殺手，如今金盆洗手，只求一處容身之所。",
  "Tăng nhân hạ sơn": "僧人下山",
  "Ni cô hạ sơn": "尼姑下山",
  "Một tăng nhân rời cửa Phật, mang theo Phật pháp lẫn một bí mật chưa nói.": "一位僧人離開佛門，身懷佛法與一樁未言明的秘密。",
  "Một ni cô rời cửa Phật, mang theo Phật pháp lẫn một bí mật chưa nói.": "一位尼姑離開佛門，身懷佛法與一樁未言明的秘密。",
  "Hiệp khách giang hồ": "江湖俠客",
  "Nữ hiệp giang hồ": "江湖女俠",
  "Hiệp khách phiêu bạt giang hồ, kiếm sắc lòng son, chưa tìm được nơi dừng chân.": "俠客漂泊江湖，劍利心赤，尚未尋得落腳之處。",
  "Nữ hiệp phiêu bạt giang hồ, kiếm sắc lòng son, chưa tìm được nơi dừng chân.": "女俠漂泊江湖，劍利心赤，尚未尋得落腳之處。",
  "Lai lịch bí ẩn": "來歷成謎",
  "Kẻ bịt mặt không rõ lai lịch, võ công cao thâm khó dò, thân thế là một dấu hỏi.": "蒙面之人來歷不明，武功高深莫測，身世是個謎。",
