  "© Tiêu Dao Lục": "© 逍遙錄",
  "Cho linh thú ăn thẳng linh thảo — hồi Thể Lực theo bậc cây và cộng Kinh Nghiệm. Bậc càng cao, một cây càng lời với linh thú mạnh.": "直接以靈草餵靈獸 — 依草階回復體力並增經驗。草階愈高，對強大靈獸愈划算。",
