  "Trứng linh thú Hỏa Lân (Truyền Thuyết). Ấp nở thành Linh Thú — tính năng đang phát triển, hãy cất giữ chờ ngày khai mở.": "火麟靈獸蛋(神品)。可孵化為靈獸——功能開發中，請妥善收藏，靜待開啟之日。",
