  "Trứng linh thú Hồ Yêu (Thường). Ấp nở thành Linh Thú — tính năng đang phát triển, hãy cất giữ chờ ngày khai mở.": "狐妖靈獸蛋(凡品)。可孵化為靈獸——功能開發中，請妥善收藏，靜待開啟之日。",
