  "Ta không hỏi tên ngươi, ngươi cũng đừng hỏi ta.": "我不問你姓名，你也休問我。",
  "Kiếm gãy rồi, nhưng tay chưa gãy.": "劍斷了，手還沒斷。",
  "Nghe nói có kẻ phá quan tháng trước. Chẳng biết thật hay đồn.": "聽說上月有人破關。不知是真是謠傳。",
  "Ngồi lâu quá, chân tê mà lòng chưa yên.": "坐得久了，腿麻而心未安。",
  "Đêm nay trăng mỏng, hợp để đi đường xa.": "今夜月薄，正宜遠行。",
  "Ai trả tiền rượu thì người đó nói, quy củ ở đây là vậy.": "誰付酒錢誰說話，此處規矩如此。",
  "Ta từng thua một trận, nhớ tới giờ.": "我曾敗過一場，至今記得。",
  "Chén này ta nhận. Có gì muốn hỏi, hỏi đi.": "這杯我受了。有什麼要問，問吧。",
  "Rượu ngon. Kẻ mời rượu thường không mời suông.": "好酒。請酒之人，多半不白請。",
  "Được, ngươi có lòng. Ta nói ngươi nghe một chuyện.": "好，你有心。我說一樁事與你聽。",
  "Đã lâu không ai mời ta. Ngồi xuống.": "許久沒人請我了。坐下。",
  "Uống thì uống, nhưng đừng hỏi chuyện năm xưa.": "喝便喝，但莫問當年事。",
  "Chén đầy thì lời cũng đầy theo.": "杯滿，話也跟著滿。",
  "Ngươi mời khéo lắm. Ta không quen thiếu nợ.": "你這酒請得巧。我不慣欠人。",
  "Cạn. Giờ thì nghe cho kỹ.": "乾了。現在仔細聽。",
  "Chuyện của ta dài, kể ra thì hết vò rượu.": "我的事說來話長，講完只怕酒罈見底。",
  "Ta đi khắp chốn, chỉ tìm một người chưa gặp.": "我走遍四方，只為尋一個未曾謀面之人。",
  "Năm xưa ta cũng như ngươi, đứng ngoài cửa quán nhìn vào.": "當年我也如你一般，站在店門外往裡看。",
  "Đừng học ta. Đường ta đi hỏng nhiều hơn nên.": "別學我。我走的路，敗多成少。",
  "Muốn mạnh thì đừng vội. Vội là chết.": "想強便莫急。急則死。",
  "Ta có một chiêu chưa từng dùng. Mong đời không phải dùng tới.": "我有一招從未用過。但願此生用不上。",
  "Kẻ mạnh không phải kẻ thắng nhiều, là kẻ còn ngồi được ở đây.": "強者不是勝得多的人，而是還能坐在這裡的人。",
  "Hỏi ít thôi. Biết nhiều quá cũng là họa.": "少問些。知道太多也是禍。",
