  "Y bát trên vai nặng hơn ta tưởng.": "肩上衣鉢,比我想的更沉。",
  "Ân Oán": "恩怨",
  "Uy Danh Tông Môn": "宗門威名",
  "Thu Nhận Làm Đệ Tử": "收為弟子",
