  "Quân trắng đi trước, tại hạ không khách khí đâu.": "白棋先行，在下不客氣了。",
  "Nước này tiền bối thấy sao?": "這一著前輩以為如何？",
  "Bàn cờ Tây Dương này lạ mắt, nhưng đạo lý vẫn thế thôi.": "這西洋棋盤看著新奇，道理卻是一樣。",
  "Các hạ cầm quân trắng, xin mời đi trước.": "閣下執白，請先行。",
  "Cờ nào cũng vậy, cốt ở người cầm quân.": "什麼棋都一樣，關鍵在執子之人。",
  "Ba mươi hai quân, sáu mươi tư ô, đủ cả một đời người.": "三十二子，六十四格，足抵一生。",
  "Khai cuộc thế nào là tuỳ các hạ, tại hạ tiếp hết.": "如何開局隨閣下，在下全接。",
  "Mã tại hạ đã cắm vào giữa trận, các hạ liệu hồn.": "在下的馬已插入陣中，閣下當心。",
  "Tượng đi chéo cả bàn, các hạ có thấy đường nó không?": "象斜行全盤，閣下看得見它的路麼？",
  "Hậu mà ra sớm quá thì chỉ tổ bị đuổi thôi.": "皇后出得太早，只會被追著跑。",
  "Tốt của các hạ đi được nửa đường rồi đấy.": "閣下的兵已走到一半了。",
  "Xe hậu đã vào, các hạ đỡ nổi không?": "車后已入陣，閣下擋得住嗎？",
  "Vua các hạ ngồi không yên rồi đấy.": "閣下的王坐不安穩了。",
  "Hàng tốt che vua đã thủng, còn gì che nữa?": "護王的兵陣已破，還有何可擋？",
  "Ván sau nhớ giữ hàng tốt trước vua cho kỹ.": "下局記得守好王前的兵。",
