  "Không dựng được chi tiết cho mục này.": "無法產生此項目的詳情。",
  "Enter": "確認鍵",
  "Gây 6 ST.": "造成6傷害。",
  "Chiêu kiếm nhập môn, thẳng tới thẳng lui. Cao thủ nào cũng khởi từ một đường kiếm mộc mạc như thế — vạn pháp quy căn.": "入門劍招，直去直回。高手皆起於這般樸拙一劍——萬法歸根。",
  "Quyền lộ khởi thủ, công thủ tương sinh. Chưa vội cầu chiêu lạ, trước hãy đứng cho vững tấn.": "拳路起手，攻守相生。莫急求奇招，先把樁站穩。",
  "4 ST · Suy Yếu 1.": "4傷害 · 虛弱1。",
  "2 ST ×2.": "2傷害×2。",
  "Thân pháp tuyệt thế, bước theo phương vị Dịch lý. Người đi như lướt trên sóng biếc, phiêu hốt vô định, lấy bộ pháp hóa giải kình đạo.": "絕世身法，依易理方位而行。人如掠於碧波，飄忽無定，以步法化解勁道。",
  "Rút 2 lá.": "抽2張牌。",
  "Bộ pháp nhẹ tựa thanh phong, tiến thoái theo tâm. Chân bước thảnh thơi mà chiêu thức nối liền chẳng dứt.": "步法輕若清風，進退隨心。腳下從容，招式連綿不絕。",
  "Nội công chí dương chí cương, chân khí sinh sinh bất tức. Luyện thành thì bách độc bất xâm, càng chiến càng hăng, khí lực vô cùng.": "內功至陽至剛，真氣生生不息。練成則百毒不侵，愈戰愈勇，氣力無窮。",
  "5 ST · Suy Yếu 2.": "5傷害 · 虛弱2。",
  "Kỳ thư đoạt tạo hóa, khiến quần hùng tranh nhau đổ máu. Nội công âm nhu tinh diệu, chiêu ra lặng lẽ mà đoạt hồn nhiếp phách.": "奇書奪造化，令群雄爭相流血。內功陰柔精妙，出招無聲卻奪魂攝魄。",
  "5 ST toàn địch.": "全敵5傷害。",
  "Một chiêu quét ngang cả trận, đãng địch như đãng lá. Khí thế ngời ngời tựa thiên binh vạn mã tràn tới.": "一招橫掃全陣，蕩敵如蕩葉。氣勢煌煌，恰似千軍萬馬湧來。",
  "18 ST · Phá Giáp · Đoạn.": "18傷害 · 破甲 · 消耗。",
  "Bá đạo trấn thế của Thiên Vương Bang. Một chưởng giáng xuống nghiền non lấp bể, uy áp muôn quân, thiên hạ khiếp phục.": "天王幫鎮世霸道。一掌落下碾山填海，威壓萬軍，天下懾服。",
  "7 ST · Phá Giáp.": "7傷害 · 破甲。",
  "Gây 11 ST.": "造成11傷害。",
  "Trấn sơn tuyệt kỹ Thiếu Lâm, mười tám vị La Hán hộ trì. Quyền cương mãnh hùng hồn, một đấm ra như sấm động, đủ hàng ma vệ đạo.": "少林鎮山絕技，十八羅漢護持。拳剛猛雄渾，一拳出如雷動，足以降魔衛道。",
  "Trượng pháp do Đạt Ma tổ sư truyền lại, cương trung hữu nhu. Một trượng quét ngang vừa khắc địch vừa lập thế thủ.": "達摩祖師所傳杖法，剛中有柔。一杖橫掃，既克敵又立守勢。",
  "Bí điển tẩy tủy dịch cân của Thiền môn. Luyện thấu thì gân cốt đổi mới, phàm thai thoát cốt, khí lực tăng tiến chẳng cùng.": "禪門洗髓易筋祕典。練透則筋骨更新，脫胎換骨，氣力增進無窮。",
  "Giảm ½ đòn kế · rút 1.": "下次受擊減半 · 抽1。",
  "4 ST ×2 · rút 1.": "4傷害×2 · 抽1。",
  "Rút 1.": "抽1張牌。",
  "5 ST · rút 1.": "5傷害 · 抽1。",
  "3 ST ×3 · rút 1.": "3傷害×3 · 抽1。",
  "6 ST ×3 · rút 2 · Giảm ½ đòn · Đoạn.": "6傷害×3 · 抽2 · 受擊減半 · 消耗。",
  "3 ST · Độc 4.": "3傷害 · 中毒4。",
  "Đường Môn đất Thục danh chấn thiên hạ vì ám khí. Mũi tiêu tẩm độc bắn ra vô thanh vô tức, thấy máu là phong hầu.": "蜀地唐門以暗器名震天下。淬毒鏢射出無聲無息，見血封喉。",
  "3 ST ×4 · Độc 2.": "3傷害×4 · 中毒2。",
  "Độc 3 · rút 2.": "中毒3 · 抽2。",
  "4 ST.": "4傷害。",
  "5 ST · Độc 2.": "5傷害 · 中毒2。",
  "2 ST ×3 · Độc 3.": "2傷害×3 · 中毒3。",
  "4 ST ×5 · Độc 2/mũi · Đoạn.": "4傷害×5 · 每鏢中毒2 · 消耗。",
  "Độc 6.": "中毒6。",
  "4 ST · Độc 3 · Suy Yếu 1.": "4傷害 · 中毒3 · 虛弱1。",
  "Độc 3.": "中毒3。",
  "4 ST · Độc 4.": "4傷害 · 中毒4。",
  "8 ST · Độc 3.": "8傷害 · 中毒3。",
  "Tà công nghịch thiên của Ma Giáo, hút cạn nội lực người khác nạp vào mình. Uy lực kinh người, song dị chủng chân khí xung đột, sớm muộn phản phệ.": "魔教逆天邪功，吸盡他人內力納為己有。威力驚人，然異種真氣衝突，遲早反噬。",
  "18 ST · tự −5 HP · Đoạn.": "18傷害 · 自身−5生命 · 消耗。",
  "5 ST · hút máu · Suy Yếu 1.": "5傷害 · 吸血 · 虛弱1。",
  "5 ST · hút máu.": "5傷害 · 吸血。",
  "6 ST · tự −3 HP.": "6傷害 · 自身−3生命。",
  "9 ST · tự −3 HP.": "9傷害 · 自身−3生命。",
  "10 ST · hút máu · tự −4 HP.": "10傷害 · 吸血 · 自身−4生命。",
  "Nga Mi": "峨嵋",
  "Hồi 8 HP.": "回復8生命。",
  "Chân truyền Cửu Dương của phái Nga Mi. Vận công điều tức thì nội thương tự khỏi, ôn dưỡng sinh cơ, trụ được đường dài.": "峨嵋派九陽真傳。運功調息則內傷自癒，溫養生機，久戰不衰。",
  "Hồi 4.": "回復4。",
  "5 ST · hồi 3.": "5傷害 · 回復3。",
  "Hồi 10 · rút 1.": "回復10 · 抽1。",
  "Gây 9 ST.": "造成9傷害。",
  "Kiếm tông Hoa Sơn lấy khí ngự kiếm, chiêu thức tiêu sái. Một đường lăng lệ như gió núi, chính khí lẫm nhiên soi tỏ giang hồ.": "華山劍宗以氣禦劍，招式瀟灑。一劍凌厲如山風，正氣凜然照徹江湖。",
  "4 ST · rút 1.": "4傷害 · 抽1。",
  "4 ST ×5 · rút 2 · Đoạn.": "4傷害×5 · 抽2 · 消耗。",
