  "Đánh 3 × 3 ST.": "攻擊3次 × 3傷害。",
  "Kiếm phổ tà môn nhanh đến quỷ khốc thần sầu. Ba nhát liền như một, ai thấy cũng lạnh gáy — nhưng luyện thì phải trả giá đắt.": "邪門劍譜，快得鬼哭神愁。三刀連如一刀，見者皆脊背生寒——然修習代價極重。",
  "11 ST · tự −5 HP.": "11傷害 · 自身−5生命。",
  "22 ST · tự −8 HP · Đoạn.": "22傷害 · 自身−8生命 · 消耗。",
