  "14 ST · Phá Giáp · tự −4 HP.": "14傷害 · 破甲 · 自身−4生命。",
  "Trương chân nhân ngộ đạo bên suối, thấy nước chảy đá mòn mà thành quyền. Một vòng thái cực bao la, dĩ tĩnh chế động, tứ lạng bạt thiên cân.": "張真人溪畔悟道，見水滴石穿而成拳。一圈太極浩渺，以靜制動，四兩撥千斤。",
