  "Thẻ Công đầu tiên mỗi lượt gây thêm 3 sát thương.": "每回合首張攻擊牌額外造成3點傷害。",
  "Thẻ gây Độc áp dụng thêm 2 Độc.": "造成中毒的牌額外施加2層中毒。",
  "Độc hành vô ảnh, sát nhân vô thanh. Kẻ này không trọng cường công, chỉ lấy kỳ độc nhập mạch, loạn khí, tổn thần. Một khi độc tức đã thấm kinh lạc, sinh tử liền khó thoát khỏi lòng bàn tay.": "獨行無影，殺人無聲。此人不重強攻，只以奇毒入脈，亂氣損神。毒息一旦滲入經絡，生死便難逃掌心。",
  "Đầu lượt, nhận 3 Hộ Thể.": "回合開始時獲得3點護體。",
