  "Hộp quà không mang được kinh nghiệm. Trần Bạc nằm dưới sàn ghi sổ của chốt chống gian lận, nên tặng quà không đẩy người nhận vào sổ nghi vấn.": "禮盒不可攜帶經驗。銀兩上限低於反作弊關卡的記錄門檻，故贈禮不會將收禮者推入嫌疑名冊。",
  "Lập Tiên Minh là làm": "創立仙盟即為",
  "Mười vùng giang hồ, mỗi mùa một lần phân cao thấp. Yêu huyết đổ nơi nào, cờ Tiên Minh dựng nơi ấy.": "江湖十域，每季一分高下。妖血灑於何處，仙盟旗便立於何處。",
