  "Trang Bị ·": "裝備 ·",
  "Tua nhanh để xem Danh Sĩ tử vong/truyền nhân + bot + timer Tông Môn. Session-only (reload về thực). Lưu ý: tua rồi để timer Tông Môn chạy thì đừng \"Về thực\" giữa chừng (timer có thể kẹt) — dùng nút \"Hoàn tất timer\".": "快進以觀察名士死亡／傳人 + 機器人 + 宗門計時。僅限本次連線（重新載入即回真實時間）。注意：快進後若讓宗門計時繼續走，切勿中途「回真實」（計時可能卡住）— 請用「完成計時」按鈕。",
  "Vượt trần thì ghi sổ. Vượt từ": "越限即記錄。超出",
  "trở lên thì máy chủ từ chối luôn bản lưu đó.\r\n              Tài khoản của ngươi không bao giờ bị chặn.": "倍以上，伺服器將直接拒收該存檔。你的帳號絕不會被封鎖。",
