  "hừng hực.": "熊熊烈烈。",
  "kình lực": "勁力",
  "lạnh thấu xương.": "寒徹入骨。",
  "rắn rỏi nổi lên, da thịt loé ánh kim.": "堅硬崛起，皮肉閃出金光。",
  "sinh sôi, độc vụ phảng phất.": "滋生蔓長，毒霧隱約瀰漫。",
  "sắc lạnh, lông da cứng tựa giáp sắt.": "銳利冰冷，皮毛硬如鐵甲。",
  "thiêu đốt, sát khí ngùn ngụt.": "焚燒不止，殺氣騰騰。",
  "trầm lạnh cuồn cuộn dâng lên.": "沉寒滾滾湧起。",
  "trầm trọng vững như non.": "沉重穩如山嶽。",
  "xanh rì, sinh cơ lẫn độc khí đan cài.": "青翠欲滴，生機與毒氣交織。",
  "âm trầm trỗi dậy.": "陰沉升騰。",
  "# # — ngươi lách mình tránh gọn, không hề hấn gì.": "# # — 你側身避開，毫髮無傷。",
  "# # — ngươi lãnh trọn": "# # — 你硬受",
  "# #, bổ vào ngươi": "# #，劈中你造成",
  "# #, ngươi đỡ không trọn, mất": "# #，你格擋不全，失去",
  "# #, nhưng ngươi thân pháp như mây trôi, nhẹ nhàng né thoát.": "# #，然你身法如行雲，輕巧閃脫。",
  "# bốc cháy phừng phừng, tổn": "#烈焰騰身，損",
  "# gầm lên, toàn thân bốc cháy rừng rực, ngưng tụ một thân": "#咆哮一聲，渾身烈焰騰騰，凝聚一身",
  "# khí hộ thể của địch dày như thành, gạt đi #% uy lực.": "敵人的#氣護體厚如城牆，卸去 #% 威力。",
  "# kình quán vào #, hao": "#勁貫入#，耗",
  "# lách mình né gọn — ngươi đánh hụt.": "#側身避開 — 你落了空。",
  "# lãnh trọn": "#硬受",
  "# lãnh trọn một đạo # kình, tổn": "#硬受一道#勁，損",
  "# mắt đỏ như than, vận khởi": "#雙目赤如炭火，運起",
  "# ngưng tụ": "#凝聚",
  "# thân hình một thoáng nhoè đi, đòn của ngươi chém trượt vào khoảng không.": "#身形一瞬模糊，你這一擊斬入虛空。",
  "# toả": "#散發",
  "Cỏ cây quanh # rạp xuống, một thân": "#四周草木伏倒，一身",
  "Hàn khí buốt giá lan toả, # ngưng một thân": "刺骨寒氣蔓延，#凝起一身",
  "Ngươi ra đòn quá lộ, # đã kịp lùi khỏi tầm.": "你出招過於明顯，#已及時退出攻擊範圍。",
  "Thân nó vốn nhuốm # khí, kình # rót vào như đá chìm biển — chặn mất #%.": "它本身便浸染#氣，#勁灌入猶如石沉大海 — 被擋去 #%。",
  "hỏa khí cuồn cuộn nuốt lấy #, hao": "火氣翻捲吞沒#，耗",
  "ngươi đảo bộ phiêu hốt, đòn # của # đánh vào khoảng không.": "你步法飄忽，#的#招打入虛空。",
  "sát thương # lên #": "#傷害於#",
  "sát thương Hỏa lên mình #": "火傷害於#",
  "sát thương lên #": "傷害於#",
