  "thiêu # mất": "焚#損",
  "âm nhu mà hàn liệt quấn riết lấy #.": "，陰柔而酷寒，緊纏著#。",
  "Đất đá rung chuyển, # ngưng một thân": "地石震動，#凝起一身",
