  "✅ # rống lên thê lương rồi đổ gục. Hạ sau #s · Sinh Lực còn #% · +# EXP#.": "✅ #哀嚎一聲倒地。#秒內擊倒 · 生命剩 #% · +# 經驗#。",
  "✅ Một chiêu định đoạt, # tắt thở đổ rạp. (#s · còn #% · +# EXP#)": "✅ 一招定勝負，#氣絕倒地。（#秒 · 剩 #% · +# 經驗#）",
  "💀 # tung đòn cuối, ngươi đỡ không nổi, thổ huyết ngã quỵ — TRỌNG THƯƠNG!": "💀 #使出最後一擊，你擋不住，吐血倒地 — 重傷！",
  "💀 Một kích xuyên thấu tạng phủ, ngươi gục trước # — TRỌNG THƯƠNG!": "💀 一擊貫穿臟腑，你倒在#面前 — 重傷！",
