  "khổ luyện có thành, đột phá lên Lv #": "苦練有成，突破至 Lv #",
  "lĩnh ngộ chân ý, công lực đại tiến đạt Lv #": "領悟真意，功力大進達 Lv #",
  "một bàn mỹ vị danh chấn #": "一桌美饌名震#",
  "ngao du #, gặp một đoạn kỳ duyên hiếm có": "遨遊#，遇一段難得奇緣",
  "nơi # câu được": "於#釣得",
  "thiền tọa nơi #, đạo tâm thông triệt": "於#禪坐，道心通透",
  "tinh thông #, được muôn người kính nể": "精通#，為萬人敬重",
  "# có duyên gặp gỡ tông môn ngươi, truyền lại một phần tâm đắc võ học cùng chút lễ vật giang hồ làm quà kết giao.": "#有緣造訪你的宗門，傳下一部分平生武學心得，另附些許江湖禮物以結交情。",
  "# là mối họa tà đạo đang bị giang hồ truy nã. Tông môn đủ thực lực ra tay trừ gian sẽ được trọng thưởng uy danh.": "#是遭江湖通緝的邪道禍患。實力足夠出手除奸的宗門將獲重賞威名。",
  "# nghe danh tông phong của ngươi, ngỏ ý đầu nhập làm đệ tử, mang theo sở học bình sinh truyền lại cho tông môn. Chỉ tông môn đủ uy vọng mới giữ chân nổi cao nhân — thu nhận thì danh chấn giang hồ.": "#聞你宗門之風，有意投入門下為弟子，將平生所學傳與宗門。唯有威望足夠的宗門才留得住高人 — 收下便名震江湖。",
  "Bóng tiền nhân # quá lớn — ta phải bước ra khỏi cái bóng ấy, hay nương theo nó?": "前人#的影子太大 — 我該走出那道影子，還是依傍著它？",
  "Bế quan # ngày, công lực lại tiến thêm một tầng.": "閉關 # 日，功力又進一層。",
  "Kế thừa y bát #, nối chí tiền nhân # — quyết không để danh môn lụi tàn trong tay mình.": "承繼#的衣缽，繼前人#之志 — 決不讓名門在自己手中衰敗。",
  "Kết oán với # 「#」 — #.": "與# 「#」結怨 — #。",
  "Luận võ bại dưới tay # 「#」, đối thủ #.": "論武敗於# 「#」之手，對手#。",
  "Luận võ thắng # 「#」 — #.": "論武勝過# 「#」 — #。",
  "Tiền nhân # 「#」 tạ thế — # kế thừa y bát #, gánh vác sư môn.": "前人# 「#」辭世 — #承繼#的衣缽，扛起師門。",
  "Truyền nhân tân tiến của #, kế thừa y bát #. Chưa có ân oán gì với ngươi — nhưng cái bóng tiền nhân buộc hậu bối phải sớm chọn bạn hay thù.": "#新晉的傳人，承繼#的衣缽。與你尚無恩怨 — 然前人的影子逼得後輩須及早擇友或擇敵。",
  "Truyền nhân đời thứ nhất của #. Khi tiền bối # 「#」 tạ thế, # được chọn kế thừa y bát, gánh trên vai cả thanh danh lẫn ân oán của sư môn. Tuổi trẻ chí lớn, còn non kinh nghiệm nhưng căn cơ đã vững — giang hồ đang chờ xem hậu bối có giữ nổi ngọn đèn tổ truyền.": "#的第一代傳人。前輩# 「#」辭世之時，#獲選承繼衣缽，肩上扛起師門的聲名與恩怨。年少志大，經驗尚淺而根基已穩 — 江湖正等著看這後輩守不守得住那盞祖傳的燈。",
  "Tuyệt học trấn phái # truyền tới tay hậu bối — uy lực còn đó, hỏa hầu chờ ngày viên mãn.": "鎮派絕學#傳到後輩手中 — 威力猶在，火候尚待圓滿之日。",
  "Tình cờ đắc một mảnh tàn quyển nơi #.": "偶得一片殘卷於#。",
  "Ác chiến nơi #, trảm một yêu thú khét tiếng.": "於#惡戰，斬一頭聲名狼藉的妖獸。",
  "Đại chiến với # 「#」 tại # — #.": "與# 「#」大戰於# — #。",
  "Cơ quan kích phát, ngươi cậy": "機關觸發，你倚仗",
  "Cổ rương khoá chặt, phá không nổi mà dính phản phệ — tổn": "古箱鎖死，破之不開反遭反噬 — 損",
  "Gặp kỳ ngộ giữa đường — nhặt thêm chiến lợi phẩm, sinh lực vẹn nguyên.": "途中遇奇緣 — 多拾戰利品，生命無損。",
  "Sinh lực cạn kiệt, ngươi buộc phải": "生命耗盡，你只得",
  "Trúng cạm bẫy cơ quan, né không kịp — tổn": "中了機關陷阱，閃避不及 — 損",
  "giáng thế! Tử chiến hạ gục — hao": "降世！死戰擊倒 — 耗",
  "lao ra cản đường — ngươi đánh dạt, hao": "衝出攔路 — 你將其擊退，耗",
  "né gọn — bình an vô sự.": "俐落閃過 — 平安無事。",
  "quá mạnh, sinh lực đã cạn — đành": "太強而生命已盡 — 只得",
  "trấn giữ tầng sâu — ác chiến hạ gục, hao": "鎮守深層 — 惡戰擊倒，耗",
  "Đàn": "法壇",
  "đoạt trân bảo!": "奪得珍寶！",
  "Trước cổ rương phong ấn, ngươi #": "面對封印古箱，你#",
  "khỏi #.": "脫離#。",
  "ngấm vào tạng phủ — # chưa đủ, tổn": "滲入臟腑 — #不足，損",
  "ập tới, # thâm hậu chống đỡ ung dung — chỉ hao": "襲來，你深厚的#從容抵住 — 只耗",
  "trễ": "遲",
  "tệ nhất": "最差",
  "→ Nếu là chữ PHỒN THỂ mà đòi Ma Shan Zheng thì vô ích: font đó chỉ có giản thể.": "→ 若為繁體字而指定 Ma Shan Zheng 則無用：該字型只有簡體。",
  "# thi triển 〈#〉, #": "#施展〈#〉，#",
