  "Hiệp #: # dốc toàn lực một chiêu định thắng bại — # gục xuống nhận thua.": "第 # 回合：#傾盡全力一招定勝負 — #倒地認輸。",
  "# bắt đầu lĩnh ngộ 「#」 (#h).": "#開始領悟「#」（#小時）。",
  "# bế quan nghiền ngẫm, lĩnh ngộ thành công 「#」!": "#閉關鑽研，成功領悟「#」！",
  "# bị Giới Luật Đường trách phạt mà trong lòng bất phục, ngầm sinh oán khí.": "#遭戒律堂責罰而心中不服，暗生怨氣。",
  "# bị phạt nhưng sinh bất phục — coi chừng hậu họa.": "#受罰卻不服 — 慎防後患。",
  "# chịu Giới Luật Đường răn dạy, gột tâm ma tịnh đạo — sơn môn thêm nghiêm cẩn.": "#受戒律堂訓誡，滌魔淨道 — 山門更為嚴謹。",
  "# gắng gượng đón thiên lôi, song đến đạo thứ bảy thì chân nguyên cạn kiệt, hộc một ngụm máu tươi ngã quỵ giữa kiếp vân. Mây sét tan đi, để lại y thoi thóp trong vũng máu — đạo cơ chấn động, tâm ma quấy thêm một tầng. Lần này chưa thành, nhưng mạng còn thì còn cơ hội.": "#強撐迎接天雷，然至第七道時真元耗竭，噴出一口鮮血倒在劫雲之下。雷雲散去，只留他奄奄一息躺在血泊裡 — 道基震動，心魔又攪深一層。此番未成，然命在便還有機會。",
  "# hết ô võ học (trần # theo cảnh giới).": "#武學欄位已滿（上限 # 依境界而定）。",
  "# khởi hành lịch luyện (#h).": "#啟程歷練（#小時）。",
  "# lịch luyện trở về, mang theo #.": "#歷練歸來，帶回#。",
  "# mãn khóa thính giảng trở về, tư chất đã chạm giới hạn.": "#聽講期滿而歸，資質已達極限。",
  "# phục một viên #, đột phá #!": "#服下一枚#，突破#！",
  "# thính giảng đắc ngộ, trần tư chất nới rộng — vươn tới #.": "#聽講得悟，資質上限拓寬 — 達至#。",
  "# tu vi viên mãn #, lâm Bình Cảnh — chờ đột phá đại cảnh.": "#修為圓滿於#，臨瓶頸 — 待突破大境界。",
  "# vào Giảng Đạo Đường thính giảng (#h).": "#進講道堂聽講（#小時）。",
  "# vừa bị răn, đang tĩnh tâm.": "#剛受訓誡，正在靜心。",
  "# vừa tỉ thí, đợi hồi sức.": "#方才比試，正待回氣。",
  "# đã thông 「#」.": "#已通「#」。",
  "# đã được răn dạy · tâm ma −##.": "#已受訓誡 · 心魔 −##。",
  "# đêm khuya tâm ma quấy nhiễu, tự toạ thiền áp chế — đạo tâm gợn sóng (#).": "#深夜遭心魔擾動，自行坐禪壓制 — 道心起波瀾（#）。",
  "# đạo tâm trong sáng, không cần răn dạy.": "#道心清明，無須訓誡。",
  "# độ # thất bại — đạo cơ chấn động, may giữ được mạng, lui về tĩnh dưỡng dưỡng thương.": "#渡#失敗 — 道基震動，幸而保命，退回靜養療傷。",
  "# đột phá #!": "#突破#！",
  "# ở lại làm Trưởng Lão, truyền dạy hậu bối.": "#留任長老，傳授後輩。",
