  ". Hai đường thưởng dùng chung hệ số.": "。兩條獎勵路徑共用同一係數。",
  ". Nhờ vậy thắng bài không sinh ra Bạc — các trò này cách ly khỏi kinh tế chính, không ảnh hưởng cân bằng cày cuốc.": "。因此贏牌不會產生銀兩 — 這些牌戲與主經濟隔離，不影響刷怪平衡。",
  ". Quái hạ trước khi nhận không được tính.": "。領取之前擊殺的妖獸不予計算。",
