  "Khắc +#, bị khắc −#.": "相剋 +#，被剋 −#。",
  "Kết quả khi treo máy và khi ngồi xem là": "掛機與在場觀看的結果是",
  "Lv # phút": "Lv # 分鐘",
  "Nhịp # giây một trận, diễn tự động.": "每 # 秒一戰，自動演算。",
  "Trong đó có": "其中包含",
  "Truy Nã chụp mốc số quái đã hạ tại thời điểm": "通緝令會在此刻擷取已擊殺妖獸數：",
  "Trần luyện #, trần thật #.": "修煉上限 #，實際上限 #。",
  "Trứng Linh Thú chỉ rơi ở đây. Tỉ lệ từng bậc trứng xem ở bảng": "靈獸蛋只在此處掉落。各級蛋的機率見表",
  "Tích theo thời gian tu luyện, tối đa # tầng": "隨修煉時間累積，最多 # 層",
