  "Bậc cao nhất; cần đồ phổ, nguyên liệu hiếm và # Bạc": "最高階；需圖譜、稀有材料與 # 銀兩",
  "Mùa # ngày; hạng vùng cho buff nghề.": "賽季 # 天；地域名次提供職業增益。",
  "Trần kháng #; Tâm Pháp cho sẵn # hệ mình.": "抗性上限 #；心法直接給予 # 點本系。",
  "bộ; dòng ẩn mở ở mốc 3, 5, 7 món.": "套；隱藏詞條於 3、5、7 件時開啟。",
  "loại dòng phụ; # bậc thỏi cường hoá.": "種副詞條；強化用錠共 # 階。",
  "ô công cụ; cộng thẳng vào hiệu suất nghề.": "個工具格；直接計入職業效率。",
  "# bế quan đã ba ngày không xuất. Ngươi đẩy cửa thạch thất: y ngồi giữa vũng nến chảy, mắt nhắm nghiền mà lệ máu rỉ hai bên thái dương, miệng lẩm nhẩm những lời chẳng phải của mình. Tâm ma 「#」 ủ bấy lâu nay phá phong trỗi dậy — kinh mạch gào thét, đạo tâm rạn như băng tiết xuân. Một niệm sai, bao năm khổ tu hóa tro bụi; một niệm vững, kiếp nạn lại hóa cơ duyên. Chưởng Môn, ngươi định liệu thế nào?": "#閉關已三日未出。你推開石室之門：他坐在一灘燭淚之中，雙目緊閉而血淚自兩鬢滲出，口中喃喃著並非自己的話語。積蓄已久的心魔「#」破封而起 — 經脈嘶號，道心裂如春初之冰。一念之差，多年苦修化為灰燼；一念之堅，劫難反成機緣。掌門，你意下如何？",
  "Giang hồ còn nhớ tên #; bao giờ họ mới nhớ tên ta?": "江湖仍記得#之名；何時才會記得我的名字？",
  "Hiệp #: ngũ hành tương khắc phát uy — #; #.": "第 # 回合：五行相剋顯威 — #；#。",
  "Hiệp #: võ học khắc chế lẫn nhau — #; #.": "第 # 回合：武學互相剋制 — #；#。",
  "Tông Môn dùng để chiêu mộ và bồi dưỡng đệ tử; Bang Phái dùng cho tranh đấu và hoạt động tập thể. Hai hệ thống có vai trò riêng, không thay thế cho nhau.": "宗門用於招募與培養弟子；幫派用於爭鬥與集體活動。兩套系統各司其職，不能互相取代。",
  "Băng tâm vô cấu, đạo niệm bất động. Trước vạn chiêu biến hóa vẫn tĩnh như hàn đàm, trước sát khí ngập trời vẫn lạnh tựa tuyết lĩnh. Tâm càng tĩnh, ý càng minh; ý càng minh, sát cơ càng chuẩn.": "冰心無垢，道念不動。面對萬招變化仍靜如寒潭，面對漫天殺氣仍冷似雪嶺。心愈靜則意愈明；意愈明則殺機愈準。",
  "Luyện thể thành cương, huyết nhục hóa thiết. Ngoại lực nan xâm, đao binh bất phá. Thân như kim thạch, khí trấn sơn hà; lâm trận càng lâu, hộ thể càng thịnh.": "練體成剛，血肉化鐵。外力難侵，刀兵不破。身如金石，氣鎮山河；臨陣愈久，護體愈盛。",
  "Nhất khí quy nguyên, vạn pháp quy tông. Không chấp quyền chưởng, chẳng nệ binh khí; khí vận chu thiên, thế sinh vô cực. Một hơi chân khí chưa tuyệt, càn khôn vẫn còn khả chuyển.": "一氣歸元，萬法歸宗。不執拳掌，不拘兵器；氣運周天，勢生無極。只要一息真氣未絕，乾坤仍可扭轉。",
  "Nộ hỏa tàng tâm, chiến ý nhập cốt. Càng bị áp chế, hung khí càng thịnh; càng lâm tuyệt cảnh, sát lực càng cuồng. Một niệm phẫn khởi, phá trận khai sinh lộ.": "怒火藏心，戰意入骨。愈受壓制，兇氣愈盛；愈臨絕境，殺力愈狂。一念憤起，破陣開生路。",
  "Vô môn vô phái, độc bộ thiên nhai. Nhất kiếm tùy thân, bán sinh phong trần. Kiếm vị xuất, sát cơ tiên khởi; hàn quang nhất thiểm, thắng phụ dĩ phân.": "無門無派，獨步天涯。一劍隨身，半生風塵。劍未出鞘，殺機先起；寒光一閃，勝負已分。",
  "Bậc cao nhất; cần đồ phổ, nguyên liệu hiếm và": "最高階；需圖譜、稀有材料與",
  "loại dòng phụ;": "種副詞條；",
  "ngày; hạng vùng cho buff nghề.": "天；地域名次提供職業增益。",
  "Linh Thạch có thời lượng hoạt động; hết viên này thì tự đốt viên cùng loại kế tiếp. Hết sạch thì việc vẫn chạy, chỉ mất phần cộng thêm.": "靈石有其運作時長；一枚燒盡便自動接燒同類的下一枚。全部用盡後工作仍會進行，只是少了加成。",
